-- MIGRATION 030_snag_list_foundation.sql SHA256 04843f8589fbaad18c6d47aa6733fc26b6bf52303d0bb8b4846819d725312bf0
-- 030_snag_list_foundation.sql
-- Headless Snag List aggregate, append-only history, evidence metadata and atomic commands.

CREATE TABLE public.snag_plan_versions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id bigint NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,
  name text NOT NULL CHECK (btrim(name) <> ''), version text NOT NULL CHECK (btrim(version) <> ''),
  storage_path text NOT NULL CHECK (btrim(storage_path) <> ''), mime_type text NOT NULL DEFAULT 'application/pdf',
  page_count integer CHECK (page_count > 0), created_by uuid NOT NULL REFERENCES auth.users(id),
  created_at timestamptz NOT NULL DEFAULT now(), is_active boolean NOT NULL DEFAULT true,
  UNIQUE(project_id, version)
);

CREATE TABLE public.snags (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id bigint NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,
  snag_number integer NOT NULL CHECK (snag_number > 0), title text NOT NULL CHECK (btrim(title) <> ''), description text NOT NULL DEFAULT '',
  category_code text NOT NULL, discipline_code text NOT NULL, priority text NOT NULL CHECK (priority IN ('LOW','MEDIUM','HIGH','CRITICAL')),
  status text NOT NULL CHECK (status IN ('OPEN','ASSIGNED','IN_PROGRESS','READY_FOR_REVIEW','CLOSED','CANCELLED')),
  assignee_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, due_date date,
  location_zone_id text, location_level text, location_room text, location_text text,
  plan_version_id uuid REFERENCES public.snag_plan_versions(id) ON DELETE RESTRICT,
  plan_x numeric, plan_y numeric, location_schema_version integer NOT NULL DEFAULT 1,
  created_by uuid NOT NULL REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
  closed_at timestamptz, cancelled_at timestamptz, version integer NOT NULL DEFAULT 1 CHECK (version > 0), schema_version integer NOT NULL DEFAULT 1, workflow_version integer NOT NULL DEFAULT 1,
  UNIQUE(project_id, snag_number),
  CHECK (location_zone_id IS NOT NULL OR location_level IS NOT NULL OR location_room IS NOT NULL OR location_text IS NOT NULL),
  CHECK ((plan_x IS NULL AND plan_y IS NULL) OR (plan_version_id IS NOT NULL AND plan_x BETWEEN 0 AND 1 AND plan_y BETWEEN 0 AND 1)),
  CHECK ((status = 'CLOSED') = (closed_at IS NOT NULL)),
  CHECK ((status = 'CANCELLED') = (cancelled_at IS NOT NULL))
);

CREATE TABLE public.snag_events (
  id bigserial PRIMARY KEY, snag_id uuid NOT NULL REFERENCES public.snags(id) ON DELETE CASCADE,
  project_id bigint NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE, actor_id uuid NOT NULL REFERENCES auth.users(id),
  event_type text NOT NULL, previous_state jsonb, new_state jsonb, reason text, source_command_id uuid NOT NULL,
  occurred_at timestamptz NOT NULL DEFAULT now(), schema_version integer NOT NULL DEFAULT 1,
  UNIQUE(actor_id, source_command_id)
);

CREATE TABLE public.snag_evidence (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), snag_id uuid NOT NULL REFERENCES public.snags(id) ON DELETE CASCADE,
  evidence_type text NOT NULL CHECK (btrim(evidence_type) <> ''), storage_path text NOT NULL CHECK (btrim(storage_path) <> ''),
  note text NOT NULL DEFAULT '', created_by uuid NOT NULL REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now(),
  transition_event_id bigint REFERENCES public.snag_events(id) ON DELETE SET NULL
);

CREATE TABLE public.snag_command_requests (
  actor_id uuid NOT NULL REFERENCES auth.users(id), client_request_id uuid NOT NULL, project_id bigint NOT NULL REFERENCES public.projects(id),
  command_type text NOT NULL, request_payload jsonb NOT NULL, response jsonb, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz,
  PRIMARY KEY(actor_id, client_request_id)
);

CREATE INDEX idx_snags_project_status ON public.snags(project_id,status);
CREATE INDEX idx_snags_assignee_status ON public.snags(assignee_id,status);
CREATE INDEX idx_snags_project_due ON public.snags(project_id,due_date) WHERE due_date IS NOT NULL;
CREATE INDEX idx_snags_project_filters ON public.snags(project_id,category_code,discipline_code,priority);
CREATE INDEX idx_snag_events_snag_time ON public.snag_events(snag_id,occurred_at,id);
CREATE INDEX idx_snag_evidence_snag_time ON public.snag_evidence(snag_id,created_at);

ALTER TABLE public.snag_plan_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.snags ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.snag_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.snag_evidence ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.snag_command_requests ENABLE ROW LEVEL SECURITY;

CREATE POLICY snag_plan_versions_select ON public.snag_plan_versions FOR SELECT TO authenticated USING (public.can_access_project(project_id));
CREATE POLICY snags_select ON public.snags FOR SELECT TO authenticated USING (public.can_access_project(project_id));
CREATE POLICY snag_events_select ON public.snag_events FOR SELECT TO authenticated USING (public.can_access_project(project_id));
CREATE POLICY snag_evidence_select ON public.snag_evidence FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.snags s WHERE s.id=snag_id AND public.can_access_project(s.project_id)));

REVOKE ALL ON public.snag_plan_versions, public.snags, public.snag_events, public.snag_evidence, public.snag_command_requests FROM anon, authenticated;
GRANT SELECT ON public.snag_plan_versions, public.snags, public.snag_events, public.snag_evidence TO authenticated;

CREATE OR REPLACE FUNCTION public.prevent_snag_event_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'SNAG_EVENT_IMMUTABLE' USING ERRCODE='55000'; END; $$;
CREATE TRIGGER snag_events_immutable BEFORE UPDATE OR DELETE ON public.snag_events FOR EACH ROW EXECUTE FUNCTION public.prevent_snag_event_mutation();

CREATE OR REPLACE FUNCTION public.execute_snag_command(p_command jsonb, p_client_request_id uuid, p_expected_version integer DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
  v_uid uuid := auth.uid(); v_role text; v_type text := p_command->>'type'; v_project_id bigint := (p_command->>'projectId')::bigint;
  v_snag_id uuid := NULLIF(p_command->>'snagId','')::uuid; v_payload jsonb := COALESCE(p_command->'payload','{}');
  v_req public.snag_command_requests%ROWTYPE; v_snag public.snags%ROWTYPE; v_before jsonb; v_event_type text; v_reason text;
  v_event_id bigint; v_evidence_id uuid; v_response jsonb; v_next_status text; v_number integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE='28000'; END IF;
  IF p_client_request_id IS NULL OR v_type IS NULL OR v_project_id IS NULL THEN RAISE EXCEPTION 'INVALID_COMMAND' USING ERRCODE='22023'; END IF;
  SELECT upper(role) INTO v_role FROM public.profiles WHERE id=v_uid;
  IF NOT public.can_access_project(v_project_id) THEN RAISE EXCEPTION 'PROJECT_ACCESS_DENIED' USING ERRCODE='42501'; END IF;
  INSERT INTO public.snag_command_requests(actor_id,client_request_id,project_id,command_type,request_payload)
  VALUES(v_uid,p_client_request_id,v_project_id,v_type,p_command)
  ON CONFLICT(actor_id,client_request_id) DO NOTHING;
  SELECT * INTO v_req FROM public.snag_command_requests WHERE actor_id=v_uid AND client_request_id=p_client_request_id FOR UPDATE;
  IF v_req.project_id<>v_project_id OR v_req.command_type<>v_type OR v_req.request_payload<>p_command THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT' USING ERRCODE='23505'; END IF;
  IF v_req.response IS NOT NULL THEN RETURN v_req.response || jsonb_build_object('idempotentReplay',true); END IF;

  IF v_type='createSnag' THEN
    IF v_role NOT IN ('ADMIN','PM') OR NOT public.can_write_project(v_project_id) THEN RAISE EXCEPTION 'COMMAND_FORBIDDEN' USING ERRCODE='42501'; END IF;
    IF btrim(COALESCE(v_payload->>'title',''))='' THEN RAISE EXCEPTION 'TITLE_REQUIRED' USING ERRCODE='22023'; END IF;
    IF btrim(COALESCE(v_payload->'location'->>'text',v_payload->'location'->>'zoneId',v_payload->'location'->>'level',v_payload->'location'->>'room',''))='' THEN RAISE EXCEPTION 'LOCATION_REQUIRED' USING ERRCODE='22023'; END IF;
    PERFORM pg_advisory_xact_lock(v_project_id);
    SELECT COALESCE(MAX(snag_number),0)+1 INTO v_number FROM public.snags WHERE project_id=v_project_id;
    INSERT INTO public.snags(project_id,snag_number,title,description,category_code,discipline_code,priority,status,assignee_id,due_date,
      location_zone_id,location_level,location_room,location_text,plan_version_id,plan_x,plan_y,created_by)
    VALUES(v_project_id,v_number,btrim(v_payload->>'title'),COALESCE(v_payload->>'description',''),COALESCE(v_payload->>'categoryCode','GENERAL'),COALESCE(v_payload->>'disciplineCode','GENERAL'),COALESCE(v_payload->>'priority','MEDIUM'),
      CASE WHEN NULLIF(v_payload->>'assigneeId','') IS NULL THEN 'OPEN' ELSE 'ASSIGNED' END,NULLIF(v_payload->>'assigneeId','')::uuid,NULLIF(v_payload->>'dueDate','')::date,
      NULLIF(v_payload->'location'->>'zoneId',''),NULLIF(v_payload->'location'->>'level',''),NULLIF(v_payload->'location'->>'room',''),NULLIF(v_payload->'location'->>'text',''),
      NULLIF(v_payload->'location'->>'planVersionId','')::uuid,NULLIF(v_payload->'location'->>'x','')::numeric,NULLIF(v_payload->'location'->>'y','')::numeric,v_uid) RETURNING * INTO v_snag;
    v_event_type:='SNAG_CREATED'; v_before:=NULL;
  ELSE
    SELECT * INTO v_snag FROM public.snags WHERE id=v_snag_id AND project_id=v_project_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'SNAG_NOT_FOUND' USING ERRCODE='P0002'; END IF;
    IF p_expected_version IS NULL OR p_expected_version<>v_snag.version THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001'; END IF;
    v_before:=to_jsonb(v_snag); v_reason:=NULLIF(btrim(v_payload->>'reason'),'');
    IF v_type IN ('startSnagWork','markSnagReadyForReview','addSnagEvidence') THEN
      IF v_role<>'CONTRACTOR' OR v_snag.assignee_id<>v_uid THEN RAISE EXCEPTION 'COMMAND_FORBIDDEN' USING ERRCODE='42501'; END IF;
    ELSIF v_role NOT IN ('ADMIN','PM') OR NOT public.can_write_project(v_project_id) THEN RAISE EXCEPTION 'COMMAND_FORBIDDEN' USING ERRCODE='42501'; END IF;

    IF v_type='assignSnag' AND v_snag.status IN ('OPEN','ASSIGNED','IN_PROGRESS','READY_FOR_REVIEW') THEN v_next_status:='ASSIGNED'; v_event_type:='SNAG_ASSIGNED'; v_snag.assignee_id:=NULLIF(v_payload->>'assigneeId','')::uuid;
    ELSIF v_type='unassignSnag' AND v_snag.status='ASSIGNED' THEN v_next_status:='OPEN'; v_event_type:='SNAG_UNASSIGNED'; v_snag.assignee_id:=NULL;
    ELSIF v_type='startSnagWork' AND v_snag.status='ASSIGNED' THEN v_next_status:='IN_PROGRESS'; v_event_type:='SNAG_STATUS_CHANGED';
    ELSIF v_type='markSnagReadyForReview' AND v_snag.status='IN_PROGRESS' THEN v_next_status:='READY_FOR_REVIEW'; v_event_type:='SNAG_STATUS_CHANGED';
    ELSIF v_type='approveAndCloseSnag' AND v_snag.status='READY_FOR_REVIEW' THEN v_next_status:='CLOSED'; v_event_type:='SNAG_CLOSED';
    ELSIF v_type='rejectSnag' AND v_snag.status='READY_FOR_REVIEW' AND v_reason IS NOT NULL THEN v_next_status:='IN_PROGRESS'; v_event_type:='SNAG_REJECTED';
    ELSIF v_type='reopenSnag' AND v_snag.status='CLOSED' AND v_reason IS NOT NULL THEN v_next_status:='IN_PROGRESS'; v_event_type:='SNAG_REOPENED';
    ELSIF v_type='cancelSnag' AND v_snag.status<>'CANCELLED' AND v_reason IS NOT NULL THEN v_next_status:='CANCELLED'; v_event_type:='SNAG_CANCELLED';
    ELSIF v_type='updateSnagDetails' AND v_snag.status NOT IN ('CLOSED','CANCELLED') THEN v_next_status:=v_snag.status; v_event_type:='SNAG_DETAILS_CHANGED';
      v_snag.title:=COALESCE(NULLIF(btrim(v_payload->>'title'),''),v_snag.title); v_snag.description:=COALESCE(v_payload->>'description',v_snag.description);
      v_snag.priority:=COALESCE(v_payload->>'priority',v_snag.priority); v_snag.due_date:=CASE WHEN v_payload ? 'dueDate' THEN NULLIF(v_payload->>'dueDate','')::date ELSE v_snag.due_date END;
    ELSIF v_type='updateSnagLocation' AND v_snag.status NOT IN ('CLOSED','CANCELLED') THEN v_next_status:=v_snag.status; v_event_type:='SNAG_LOCATION_CHANGED';
      v_snag.location_zone_id:=NULLIF(v_payload->'location'->>'zoneId',''); v_snag.location_level:=NULLIF(v_payload->'location'->>'level',''); v_snag.location_room:=NULLIF(v_payload->'location'->>'room',''); v_snag.location_text:=NULLIF(v_payload->'location'->>'text','');
      v_snag.plan_version_id:=NULLIF(v_payload->'location'->>'planVersionId','')::uuid; v_snag.plan_x:=NULLIF(v_payload->'location'->>'x','')::numeric; v_snag.plan_y:=NULLIF(v_payload->'location'->>'y','')::numeric;
    ELSIF v_type='addSnagEvidence' AND v_snag.status NOT IN ('CLOSED','CANCELLED') THEN v_next_status:=v_snag.status; v_event_type:='SNAG_EVIDENCE_ADDED';
      INSERT INTO public.snag_evidence(snag_id,evidence_type,storage_path,note,created_by) VALUES(v_snag.id,v_payload->>'evidenceType',v_payload->>'storagePath',COALESCE(v_payload->>'note',''),v_uid) RETURNING id INTO v_evidence_id;
    ELSE RAISE EXCEPTION 'INVALID_SNAG_TRANSITION' USING ERRCODE='22023'; END IF;
    UPDATE public.snags SET title=v_snag.title,description=v_snag.description,priority=v_snag.priority,due_date=v_snag.due_date,
      status=v_next_status,assignee_id=v_snag.assignee_id,location_zone_id=v_snag.location_zone_id,location_level=v_snag.location_level,location_room=v_snag.location_room,location_text=v_snag.location_text,
      plan_version_id=v_snag.plan_version_id,plan_x=v_snag.plan_x,plan_y=v_snag.plan_y,version=version+1,updated_at=now(),closed_at=CASE WHEN v_next_status='CLOSED' THEN now() ELSE NULL END,cancelled_at=CASE WHEN v_next_status='CANCELLED' THEN now() ELSE NULL END
    WHERE id=v_snag.id RETURNING * INTO v_snag;
  END IF;
  INSERT INTO public.snag_events(snag_id,project_id,actor_id,event_type,previous_state,new_state,reason,source_command_id)
  VALUES(v_snag.id,v_project_id,v_uid,v_event_type,v_before,to_jsonb(v_snag),v_reason,p_client_request_id) RETURNING id INTO v_event_id;
  IF v_evidence_id IS NOT NULL THEN UPDATE public.snag_evidence SET transition_event_id=v_event_id WHERE id=v_evidence_id; END IF;
  v_response:=jsonb_build_object('snag',to_jsonb(v_snag),'eventId',v_event_id,'evidenceId',v_evidence_id,'idempotentReplay',false);
  UPDATE public.snag_command_requests SET response=v_response,completed_at=now() WHERE actor_id=v_uid AND client_request_id=p_client_request_id;
  RETURN v_response;
END $$;

REVOKE ALL ON FUNCTION public.execute_snag_command(jsonb,uuid,integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.execute_snag_command(jsonb,uuid,integer) TO authenticated;
REVOKE ALL ON FUNCTION public.prevent_snag_event_mutation() FROM PUBLIC, anon, authenticated;

-- Production has broad platform default ACLs; explicitly close them on every new object.
REVOKE ALL ON SEQUENCE public.snag_events_id_seq FROM anon, authenticated;
GRANT USAGE, SELECT ON SEQUENCE public.snag_events_id_seq TO service_role;

-- MIGRATION 031_snag_reassignment_semantics.sql SHA256 9b5a6f4fea1a4755c41d45066135e763329ddd1933969e04e22dfa932deffe1a
-- 031_snag_reassignment_semantics.sql
-- Preserve active work state during reassignment and forbid silent review invalidation.

CREATE OR REPLACE FUNCTION public.enforce_snag_reassignment_semantics()
RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$
BEGIN
  IF NEW.assignee_id IS DISTINCT FROM OLD.assignee_id THEN
    IF OLD.status = 'IN_PROGRESS' AND NEW.status = 'ASSIGNED' THEN
      NEW.status := 'IN_PROGRESS';
    ELSIF OLD.status = 'READY_FOR_REVIEW' THEN
      RAISE EXCEPTION 'READY_SNAG_REASSIGNMENT_REQUIRES_EXPLICIT_REJECTION' USING ERRCODE='22023';
    END IF;
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER snags_reassignment_semantics
BEFORE UPDATE OF assignee_id, status ON public.snags
FOR EACH ROW EXECUTE FUNCTION public.enforce_snag_reassignment_semantics();

REVOKE ALL ON FUNCTION public.enforce_snag_reassignment_semantics() FROM PUBLIC, anon, authenticated;

-- MIGRATION 032_snag_project_contractors_rpc.sql SHA256 b0495a7a0f1f51a288ba1480a84c468a22f2a2cb51245a537dbd9ea6f4566de3
-- Phase 2: narrow contractor lookup for the Snag assignment UI.
-- Profiles RLS remains unchanged; callers receive only contractors who can access
-- the requested project in the caller's company.
CREATE OR REPLACE FUNCTION public.list_snag_project_contractors(p_project_id bigint)
RETURNS TABLE(id uuid, name text, email text, role text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_role text;
  v_company_id text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE='42501'; END IF;
  SELECT lower(p.role), p.company_id INTO v_role, v_company_id FROM public.profiles p WHERE p.id=auth.uid();
  IF v_role NOT IN ('admin','pm') OR NOT public.can_access_project(p_project_id) THEN
    RAISE EXCEPTION 'PROJECT_ACCESS_DENIED' USING ERRCODE='42501';
  END IF;
  RETURN QUERY
    SELECT p.id,p.name,p.email,p.role
    FROM public.profiles p
    WHERE lower(p.role)='contractor'
      AND p.company_id=v_company_id
      AND p_project_id=ANY(COALESCE(p.assigned_projects,'{}'::integer[])::bigint[])
    ORDER BY p.name,p.email,p.id;
END;
$$;

REVOKE ALL ON FUNCTION public.list_snag_project_contractors(bigint) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.list_snag_project_contractors(bigint) TO authenticated;

-- MIGRATION 033_snag_private_plan_pinning.sql SHA256 63d809642b79c23553c9fca6e1d3e1fc0e39e99780bde1eeff91c39fad0fb6fb
-- Phase 3: private immutable PDF plans and page-bound normalized snag pins.
ALTER TABLE public.snag_plan_versions
  ADD COLUMN original_filename text,
  ADD COLUMN byte_size bigint CHECK (byte_size > 0 AND byte_size <= 20971520),
  ADD COLUMN archived_at timestamptz,
  ADD COLUMN schema_version integer NOT NULL DEFAULT 2 CHECK (schema_version > 0);

ALTER TABLE public.snags ADD COLUMN plan_page_number integer;
ALTER TABLE public.snags ADD CONSTRAINT snags_plan_location_complete CHECK (
  (plan_version_id IS NULL AND plan_page_number IS NULL AND plan_x IS NULL AND plan_y IS NULL)
  OR (plan_version_id IS NOT NULL AND plan_page_number > 0 AND plan_x BETWEEN 0 AND 1 AND plan_y BETWEEN 0 AND 1)
);
CREATE UNIQUE INDEX snag_plan_versions_one_active_per_project
  ON public.snag_plan_versions(project_id) WHERE is_active AND archived_at IS NULL;
CREATE INDEX idx_snags_plan_page ON public.snags(plan_version_id,plan_page_number) WHERE plan_version_id IS NOT NULL;

CREATE OR REPLACE FUNCTION public.validate_snag_plan_location() RETURNS trigger
LANGUAGE plpgsql SET search_path=public,pg_temp AS $$
DECLARE v_plan public.snag_plan_versions%ROWTYPE;
BEGIN
  IF NEW.plan_version_id IS NULL THEN RETURN NEW; END IF;
  SELECT * INTO v_plan FROM public.snag_plan_versions WHERE id=NEW.plan_version_id;
  IF NOT FOUND OR v_plan.project_id<>NEW.project_id THEN RAISE EXCEPTION 'PLAN_PROJECT_MISMATCH' USING ERRCODE='23514'; END IF;
  IF NEW.plan_page_number IS NULL OR NEW.plan_page_number<1 OR NEW.plan_page_number>v_plan.page_count THEN RAISE EXCEPTION 'INVALID_PLAN_PAGE' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER snags_validate_plan_location BEFORE INSERT OR UPDATE OF project_id,plan_version_id,plan_page_number,plan_x,plan_y
ON public.snags FOR EACH ROW EXECUTE FUNCTION public.validate_snag_plan_location();

INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
VALUES('snag-plans','snag-plans',false,20971520,ARRAY['application/pdf'])
ON CONFLICT(id) DO UPDATE SET public=false,file_size_limit=EXCLUDED.file_size_limit,allowed_mime_types=EXCLUDED.allowed_mime_types;

CREATE POLICY snag_plans_read ON storage.objects FOR SELECT TO authenticated USING (
  bucket_id='snag-plans' AND public.can_access_project(((storage.foldername(name))[1])::bigint)
);
CREATE POLICY snag_plans_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK (
  bucket_id='snag-plans'
  AND (storage.foldername(name))[2]=auth.uid()::text
  AND lower(storage.extension(name))='pdf'
  AND public.can_write_project(((storage.foldername(name))[1])::bigint)
  AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=auth.uid() AND lower(p.role) IN ('admin','pm'))
);
CREATE POLICY snag_plans_orphan_delete ON storage.objects FOR DELETE TO authenticated USING (
  bucket_id='snag-plans'
  AND (storage.foldername(name))[2]=auth.uid()::text
  AND public.can_write_project(((storage.foldername(name))[1])::bigint)
  AND NOT EXISTS(SELECT 1 FROM public.snag_plan_versions pv WHERE pv.storage_path=name)
);

CREATE OR REPLACE FUNCTION public.create_snag_plan_upload_intent(p_project_id bigint,p_request_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_uid uuid:=auth.uid();v_role text;
BEGIN
  SELECT lower(role) INTO v_role FROM public.profiles WHERE id=v_uid;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE='28000'; END IF;
  IF v_role NOT IN ('admin','pm') OR NOT public.can_write_project(p_project_id) THEN RAISE EXCEPTION 'PLAN_MANAGEMENT_FORBIDDEN' USING ERRCODE='42501'; END IF;
  RETURN jsonb_build_object('bucket','snag-plans','path',p_project_id::text||'/'||v_uid::text||'/'||p_request_id::text||'.pdf','requestId',p_request_id);
END $$;

CREATE OR REPLACE FUNCTION public.register_snag_plan_version(p_project_id bigint,p_request_id uuid,p_name text,p_version text,p_original_filename text,p_page_count integer)
RETURNS public.snag_plan_versions LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,storage,pg_temp AS $$
DECLARE v_uid uuid:=auth.uid();v_role text;v_path text;v_object storage.objects%ROWTYPE;v_plan public.snag_plan_versions%ROWTYPE;
BEGIN
  SELECT lower(role) INTO v_role FROM public.profiles WHERE id=v_uid;
  IF v_role NOT IN ('admin','pm') OR NOT public.can_write_project(p_project_id) THEN RAISE EXCEPTION 'PLAN_MANAGEMENT_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF btrim(coalesce(p_name,''))='' OR btrim(coalesce(p_version,''))='' OR p_page_count<1 THEN RAISE EXCEPTION 'INVALID_PLAN_METADATA' USING ERRCODE='22023'; END IF;
  v_path:=p_project_id::text||'/'||v_uid::text||'/'||p_request_id::text||'.pdf';
  SELECT * INTO v_object FROM storage.objects WHERE bucket_id='snag-plans' AND name=v_path;
  IF NOT FOUND THEN RAISE EXCEPTION 'PLAN_UPLOAD_MISSING' USING ERRCODE='P0002'; END IF;
  IF coalesce(v_object.metadata->>'mimetype','')<>'application/pdf' OR coalesce((v_object.metadata->>'size')::bigint,0)<=0 OR (v_object.metadata->>'size')::bigint>20971520 THEN RAISE EXCEPTION 'INVALID_PLAN_FILE' USING ERRCODE='22023'; END IF;
  INSERT INTO public.snag_plan_versions(project_id,name,version,storage_path,mime_type,page_count,created_by,is_active,original_filename,byte_size)
  VALUES(p_project_id,btrim(p_name),btrim(p_version),v_path,'application/pdf',p_page_count,v_uid,false,p_original_filename,(v_object.metadata->>'size')::bigint)
  RETURNING * INTO v_plan;RETURN v_plan;
END $$;

CREATE OR REPLACE FUNCTION public.set_snag_plan_lifecycle(p_plan_id uuid,p_action text)
RETURNS public.snag_plan_versions LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_uid uuid:=auth.uid();v_role text;v_plan public.snag_plan_versions%ROWTYPE;
BEGIN
  SELECT * INTO v_plan FROM public.snag_plan_versions WHERE id=p_plan_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'PLAN_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  SELECT lower(role) INTO v_role FROM public.profiles WHERE id=v_uid;
  IF v_role NOT IN ('admin','pm') OR NOT public.can_write_project(v_plan.project_id) THEN RAISE EXCEPTION 'PLAN_MANAGEMENT_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF p_action='ACTIVATE' THEN
    IF v_plan.archived_at IS NOT NULL THEN RAISE EXCEPTION 'PLAN_ARCHIVED' USING ERRCODE='22023'; END IF;
    UPDATE public.snag_plan_versions SET is_active=false WHERE project_id=v_plan.project_id AND id<>p_plan_id AND is_active;
    UPDATE public.snag_plan_versions SET is_active=true WHERE id=p_plan_id RETURNING * INTO v_plan;
  ELSIF p_action='ARCHIVE' THEN
    UPDATE public.snag_plan_versions SET is_active=false,archived_at=now() WHERE id=p_plan_id RETURNING * INTO v_plan;
  ELSE RAISE EXCEPTION 'INVALID_PLAN_ACTION' USING ERRCODE='22023'; END IF;
  RETURN v_plan;
END $$;

CREATE OR REPLACE FUNCTION public.execute_snag_plan_command(p_command jsonb,p_client_request_id uuid,p_expected_version integer DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_uid uuid:=auth.uid();v_role text;v_type text:=p_command->>'type';v_project_id bigint:=(p_command->>'projectId')::bigint;v_snag public.snags%ROWTYPE;v_plan public.snag_plan_versions%ROWTYPE;v_payload jsonb:=p_command->'payload';v_req public.snag_command_requests%ROWTYPE;v_event_id bigint;v_response jsonb;v_number integer;
BEGIN
  SELECT upper(role) INTO v_role FROM public.profiles WHERE id=v_uid;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE='28000'; END IF;
  IF v_role NOT IN ('ADMIN','PM') OR NOT public.can_write_project(v_project_id) THEN RAISE EXCEPTION 'COMMAND_FORBIDDEN' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_plan FROM public.snag_plan_versions WHERE id=(v_payload->>'planVersionId')::uuid AND project_id=v_project_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'PLAN_PROJECT_MISMATCH' USING ERRCODE='23514'; END IF;
  INSERT INTO public.snag_command_requests(actor_id,client_request_id,project_id,command_type,request_payload) VALUES(v_uid,p_client_request_id,v_project_id,v_type,p_command) ON CONFLICT DO NOTHING;
  SELECT * INTO v_req FROM public.snag_command_requests WHERE actor_id=v_uid AND client_request_id=p_client_request_id FOR UPDATE;
  IF v_req.request_payload<>p_command THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT' USING ERRCODE='23505'; END IF;
  IF v_req.response IS NOT NULL THEN RETURN v_req.response||jsonb_build_object('idempotentReplay',true); END IF;
  IF v_type='createSnagFromPlan' THEN
    PERFORM pg_advisory_xact_lock(v_project_id);SELECT coalesce(max(snag_number),0)+1 INTO v_number FROM public.snags WHERE project_id=v_project_id;
    INSERT INTO public.snags(project_id,snag_number,title,description,category_code,discipline_code,priority,status,assignee_id,due_date,location_zone_id,location_level,location_room,location_text,plan_version_id,plan_page_number,plan_x,plan_y,created_by)
    VALUES(v_project_id,v_number,btrim(v_payload->>'title'),coalesce(v_payload->>'description',''),coalesce(v_payload->>'categoryCode','GENERAL'),coalesce(v_payload->>'disciplineCode','GENERAL'),coalesce(v_payload->>'priority','MEDIUM'),CASE WHEN nullif(v_payload->>'assigneeId','') IS NULL THEN 'OPEN' ELSE 'ASSIGNED' END,nullif(v_payload->>'assigneeId','')::uuid,nullif(v_payload->>'dueDate','')::date,nullif(v_payload->'location'->>'zoneId',''),nullif(v_payload->'location'->>'level',''),nullif(v_payload->'location'->>'room',''),nullif(v_payload->'location'->>'text',''),v_plan.id,(v_payload->>'pageNumber')::integer,(v_payload->>'x')::numeric,(v_payload->>'y')::numeric,v_uid) RETURNING * INTO v_snag;
    INSERT INTO public.snag_events(snag_id,project_id,actor_id,event_type,new_state,source_command_id) VALUES(v_snag.id,v_project_id,v_uid,'SNAG_CREATED',to_jsonb(v_snag),p_client_request_id) RETURNING id INTO v_event_id;
  ELSIF v_type='updateSnagPlanLocation' THEN
    SELECT * INTO v_snag FROM public.snags WHERE id=(p_command->>'snagId')::uuid AND project_id=v_project_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'SNAG_NOT_FOUND' USING ERRCODE='P0002'; END IF;
    IF p_expected_version<>v_snag.version THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001'; END IF;
    IF v_snag.status IN ('CLOSED','CANCELLED') THEN RAISE EXCEPTION 'TERMINAL_STATE' USING ERRCODE='22023'; END IF;
    INSERT INTO public.snag_events(snag_id,project_id,actor_id,event_type,previous_state,new_state,source_command_id)
    VALUES(v_snag.id,v_project_id,v_uid,'SNAG_LOCATION_CHANGED',to_jsonb(v_snag),to_jsonb(v_snag)||jsonb_build_object('plan_version_id',v_plan.id,'plan_page_number',(v_payload->>'pageNumber')::integer,'plan_x',(v_payload->>'x')::numeric,'plan_y',(v_payload->>'y')::numeric),p_client_request_id) RETURNING id INTO v_event_id;
    UPDATE public.snags SET plan_version_id=v_plan.id,plan_page_number=(v_payload->>'pageNumber')::integer,plan_x=(v_payload->>'x')::numeric,plan_y=(v_payload->>'y')::numeric,version=version+1,updated_at=now() WHERE id=v_snag.id RETURNING * INTO v_snag;
  ELSE RAISE EXCEPTION 'INVALID_PLAN_COMMAND' USING ERRCODE='22023'; END IF;
  v_response:=jsonb_build_object('snag',to_jsonb(v_snag),'eventId',v_event_id,'idempotentReplay',false);
  UPDATE public.snag_command_requests SET response=v_response,completed_at=now() WHERE actor_id=v_uid AND client_request_id=p_client_request_id;
  RETURN v_response;
END $$;

REVOKE ALL ON FUNCTION public.create_snag_plan_upload_intent(bigint,uuid),public.register_snag_plan_version(bigint,uuid,text,text,text,integer),public.set_snag_plan_lifecycle(uuid,text),public.execute_snag_plan_command(jsonb,uuid,integer),public.validate_snag_plan_location() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_snag_plan_upload_intent(bigint,uuid),public.register_snag_plan_version(bigint,uuid,text,text,text,integer),public.set_snag_plan_lifecycle(uuid,text),public.execute_snag_plan_command(jsonb,uuid,integer) TO authenticated;

-- MIGRATION 034_snag_secure_evidence_lifecycle.sql SHA256 0d71d6185e90bd083816d73cf939798dce276e971127948576f4d7702b55a53d
-- Phase 4: private, idempotent Snag evidence lifecycle and closeout read model.
ALTER TABLE public.snag_evidence
  ADD COLUMN project_id bigint REFERENCES public.projects(id) ON DELETE CASCADE,
  ADD COLUMN original_filename text,
  ADD COLUMN mime_type text,
  ADD COLUMN byte_size bigint CHECK (byte_size IS NULL OR byte_size BETWEEN 1 AND 8388608),
  ADD COLUMN client_request_id uuid,
  ADD COLUMN capture_timestamp timestamptz,
  ADD COLUMN evidence_sequence integer CHECK (evidence_sequence IS NULL OR evidence_sequence > 0),
  ADD COLUMN checksum text,
  ADD COLUMN schema_version integer NOT NULL DEFAULT 2 CHECK (schema_version > 0);

UPDATE public.snag_evidence e SET project_id=s.project_id FROM public.snags s WHERE s.id=e.snag_id AND e.project_id IS NULL;
ALTER TABLE public.snag_evidence ALTER COLUMN project_id SET NOT NULL;
ALTER TABLE public.snag_evidence ADD CONSTRAINT snag_evidence_type_v2 CHECK (
  original_filename IS NULL OR evidence_type IN ('CONDITION','CORRECTION','VERIFICATION','GENERAL')
);
CREATE UNIQUE INDEX snag_evidence_actor_request ON public.snag_evidence(created_by,client_request_id) WHERE client_request_id IS NOT NULL;
CREATE UNIQUE INDEX snag_evidence_storage_identity ON public.snag_evidence(storage_path) WHERE original_filename IS NOT NULL;
CREATE INDEX idx_snag_evidence_project_snag_order ON public.snag_evidence(project_id,snag_id,created_at,id);

CREATE TABLE public.snag_evidence_upload_intents (
  id uuid PRIMARY KEY, project_id bigint NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,
  snag_id uuid NOT NULL REFERENCES public.snags(id) ON DELETE CASCADE, actor_id uuid NOT NULL REFERENCES auth.users(id),
  client_request_id uuid NOT NULL, expected_snag_version integer NOT NULL CHECK (expected_snag_version > 0),
  evidence_type text NOT NULL CHECK (evidence_type IN ('CONDITION','CORRECTION','VERIFICATION','GENERAL')),
  storage_path text NOT NULL UNIQUE, original_filename text NOT NULL CHECK (btrim(original_filename)<>''),
  mime_type text NOT NULL CHECK (mime_type IN ('image/jpeg','image/png','image/webp')),
  byte_size bigint NOT NULL CHECK (byte_size BETWEEN 1 AND 8388608), note text NOT NULL DEFAULT '',
  capture_timestamp timestamptz, checksum text, request_fingerprint jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT (now()+interval '24 hours'), registered_at timestamptz,
  UNIQUE(actor_id,client_request_id)
);
CREATE INDEX idx_snag_evidence_intents_expiry ON public.snag_evidence_upload_intents(expires_at) WHERE registered_at IS NULL;
ALTER TABLE public.snag_evidence_upload_intents ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.snag_evidence_upload_intents FROM anon,authenticated;
CREATE POLICY snag_evidence_intents_own_read ON public.snag_evidence_upload_intents FOR SELECT TO authenticated USING (actor_id=auth.uid());
GRANT SELECT ON public.snag_evidence_upload_intents TO authenticated;
GRANT SELECT,DELETE ON public.snag_evidence_upload_intents TO service_role;

INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
VALUES('snag-evidence','snag-evidence',false,8388608,ARRAY['image/jpeg','image/png','image/webp'])
ON CONFLICT(id) DO UPDATE SET public=false,file_size_limit=EXCLUDED.file_size_limit,allowed_mime_types=EXCLUDED.allowed_mime_types;

CREATE POLICY snag_evidence_files_read ON storage.objects FOR SELECT TO authenticated USING (
  bucket_id='snag-evidence' AND (EXISTS(
    SELECT 1 FROM public.snag_evidence e JOIN public.snags s ON s.id=e.snag_id
    WHERE e.storage_path=name AND e.project_id=s.project_id AND public.can_access_project(s.project_id)
  ) OR EXISTS(SELECT 1 FROM public.snag_evidence_upload_intents i WHERE i.storage_path=name AND i.actor_id=auth.uid() AND i.registered_at IS NULL))
);
CREATE POLICY snag_evidence_files_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK (
  bucket_id='snag-evidence' AND EXISTS(
    SELECT 1 FROM public.snag_evidence_upload_intents i JOIN public.snags s ON s.id=i.snag_id AND s.project_id=i.project_id
    WHERE i.storage_path=name AND i.actor_id=auth.uid() AND i.registered_at IS NULL AND i.expires_at>now()
      AND public.can_access_project(i.project_id)
  )
);
CREATE POLICY snag_evidence_orphan_delete ON storage.objects FOR DELETE TO authenticated USING (
  bucket_id='snag-evidence' AND EXISTS(
    SELECT 1 FROM public.snag_evidence_upload_intents i WHERE i.storage_path=name AND i.actor_id=auth.uid()
      AND i.registered_at IS NULL AND NOT EXISTS(SELECT 1 FROM public.snag_evidence e WHERE e.storage_path=name)
  )
);

CREATE OR REPLACE FUNCTION public.authorize_snag_evidence_upload(p_project_id bigint,p_snag_id uuid,p_request_id uuid,p_evidence_id uuid,p_expected_version integer,p_metadata jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_uid uuid:=auth.uid();v_role text;v_snag public.snags%ROWTYPE;v_type text:=upper(p_metadata->>'evidenceType');v_name text;v_mime text:=lower(p_metadata->>'mimeType');v_size bigint:=(p_metadata->>'byteSize')::bigint;v_path text;v_fingerprint jsonb;v_existing public.snag_evidence_upload_intents%ROWTYPE;v_count integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE='28000'; END IF;
  SELECT upper(role) INTO v_role FROM public.profiles WHERE id=v_uid;
  v_name:=regexp_replace(regexp_replace(coalesce(p_metadata->>'filename','evidence'),'[^A-Za-z0-9._-]+','-','g'),'(^[.-]+|[.-]+$)','','g');
  IF v_name='' THEN v_name:='evidence'; END IF; v_name:=left(v_name,120);
  v_path:='projects/'||p_project_id||'/snags/'||p_snag_id||'/evidence/'||p_evidence_id||'/'||v_name;
  v_fingerprint:=jsonb_build_object('projectId',p_project_id,'snagId',p_snag_id,'evidenceId',p_evidence_id,'expectedVersion',p_expected_version,'evidenceType',v_type,'filename',v_name,'mimeType',v_mime,'byteSize',v_size,'note',left(coalesce(p_metadata->>'note',''),2000),'captureTimestamp',p_metadata->>'captureTimestamp','checksum',p_metadata->>'checksum');
  SELECT * INTO v_existing FROM public.snag_evidence_upload_intents WHERE actor_id=v_uid AND client_request_id=p_request_id;
  IF FOUND THEN
    IF v_existing.request_fingerprint<>v_fingerprint THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT' USING ERRCODE='23505'; END IF;
    RETURN jsonb_build_object('bucket','snag-evidence','path',v_existing.storage_path,'evidenceId',v_existing.id,'requestId',v_existing.client_request_id,'expiresAt',v_existing.expires_at,'registered',v_existing.registered_at IS NOT NULL);
  END IF;
  SELECT * INTO v_snag FROM public.snags WHERE id=p_snag_id AND project_id=p_project_id FOR SHARE;
  IF NOT FOUND OR NOT public.can_access_project(p_project_id) THEN RAISE EXCEPTION 'EVIDENCE_ACCESS_DENIED' USING ERRCODE='42501'; END IF;
  IF v_snag.version<>p_expected_version THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001'; END IF;
  IF v_snag.status IN ('CLOSED','CANCELLED') THEN RAISE EXCEPTION 'EVIDENCE_TERMINAL_STATE' USING ERRCODE='22023'; END IF;
  IF v_role='CONTRACTOR' AND (v_snag.assignee_id<>v_uid OR v_type NOT IN ('CORRECTION','GENERAL')) THEN RAISE EXCEPTION 'EVIDENCE_ACCESS_DENIED' USING ERRCODE='42501'; END IF;
  IF v_role IN ('ADMIN','PM') AND (v_type NOT IN ('CONDITION','VERIFICATION','GENERAL') OR NOT public.can_write_project(p_project_id)) THEN RAISE EXCEPTION 'EVIDENCE_ACCESS_DENIED' USING ERRCODE='42501'; END IF;
  IF v_role NOT IN ('ADMIN','PM','CONTRACTOR') THEN RAISE EXCEPTION 'EVIDENCE_ACCESS_DENIED' USING ERRCODE='42501'; END IF;
  IF v_type NOT IN ('CONDITION','CORRECTION','VERIFICATION','GENERAL') OR v_mime NOT IN ('image/jpeg','image/png','image/webp') OR v_size NOT BETWEEN 1 AND 8388608 THEN RAISE EXCEPTION 'INVALID_EVIDENCE_FILE' USING ERRCODE='22023'; END IF;
  SELECT count(*) INTO v_count FROM public.snag_evidence WHERE snag_id=p_snag_id AND original_filename IS NOT NULL;
  IF v_count>=20 THEN RAISE EXCEPTION 'EVIDENCE_LIMIT_REACHED' USING ERRCODE='22023'; END IF;
  v_name:=regexp_replace(regexp_replace(coalesce(p_metadata->>'filename','evidence'),'[^A-Za-z0-9._-]+','-','g'),'(^[.-]+|[.-]+$)','','g');
  IF v_name='' THEN v_name:='evidence'; END IF; v_name:=left(v_name,120);
  v_path:='projects/'||p_project_id||'/snags/'||p_snag_id||'/evidence/'||p_evidence_id||'/'||v_name;
  v_fingerprint:=jsonb_build_object('projectId',p_project_id,'snagId',p_snag_id,'evidenceId',p_evidence_id,'expectedVersion',p_expected_version,'evidenceType',v_type,'filename',v_name,'mimeType',v_mime,'byteSize',v_size,'note',left(coalesce(p_metadata->>'note',''),2000),'captureTimestamp',p_metadata->>'captureTimestamp','checksum',p_metadata->>'checksum');
  INSERT INTO public.snag_evidence_upload_intents(id,project_id,snag_id,actor_id,client_request_id,expected_snag_version,evidence_type,storage_path,original_filename,mime_type,byte_size,note,capture_timestamp,checksum,request_fingerprint)
  VALUES(p_evidence_id,p_project_id,p_snag_id,v_uid,p_request_id,p_expected_version,v_type,v_path,v_name,v_mime,v_size,left(coalesce(p_metadata->>'note',''),2000),nullif(p_metadata->>'captureTimestamp','')::timestamptz,nullif(p_metadata->>'checksum',''),v_fingerprint)
  ON CONFLICT(actor_id,client_request_id) DO NOTHING;
  SELECT * INTO v_existing FROM public.snag_evidence_upload_intents WHERE actor_id=v_uid AND client_request_id=p_request_id;
  IF v_existing.request_fingerprint<>v_fingerprint THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT' USING ERRCODE='23505'; END IF;
  RETURN jsonb_build_object('bucket','snag-evidence','path',v_existing.storage_path,'evidenceId',v_existing.id,'requestId',v_existing.client_request_id,'expiresAt',v_existing.expires_at,'registered',v_existing.registered_at IS NOT NULL);
END $$;

CREATE OR REPLACE FUNCTION public.register_snag_evidence(p_request_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,storage,pg_temp AS $$
DECLARE v_uid uuid:=auth.uid();v_intent public.snag_evidence_upload_intents%ROWTYPE;v_snag public.snags%ROWTYPE;v_object storage.objects%ROWTYPE;v_evidence public.snag_evidence%ROWTYPE;v_event_id bigint;v_response jsonb;
BEGIN
  SELECT * INTO v_intent FROM public.snag_evidence_upload_intents WHERE actor_id=v_uid AND client_request_id=p_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'EVIDENCE_INTENT_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_intent.registered_at IS NOT NULL THEN SELECT * INTO v_evidence FROM public.snag_evidence WHERE id=v_intent.id; RETURN jsonb_build_object('evidence',to_jsonb(v_evidence),'idempotentReplay',true); END IF;
  SELECT * INTO v_snag FROM public.snags WHERE id=v_intent.snag_id AND project_id=v_intent.project_id FOR UPDATE;
  IF v_snag.version<>v_intent.expected_snag_version THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001'; END IF;
  IF v_snag.status IN ('CLOSED','CANCELLED') THEN RAISE EXCEPTION 'EVIDENCE_TERMINAL_STATE' USING ERRCODE='22023'; END IF;
  IF (SELECT upper(role) FROM public.profiles WHERE id=v_uid)='CONTRACTOR' AND v_snag.assignee_id<>v_uid THEN RAISE EXCEPTION 'EVIDENCE_ASSIGNMENT_CHANGED' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_object FROM storage.objects WHERE bucket_id='snag-evidence' AND name=v_intent.storage_path;
  IF NOT FOUND THEN RAISE EXCEPTION 'EVIDENCE_UPLOAD_MISSING' USING ERRCODE='P0002'; END IF;
  IF coalesce(v_object.metadata->>'mimetype','')<>v_intent.mime_type OR coalesce((v_object.metadata->>'size')::bigint,0)<>v_intent.byte_size THEN RAISE EXCEPTION 'EVIDENCE_FILE_MISMATCH' USING ERRCODE='22023'; END IF;
  UPDATE public.snags SET version=version+1,updated_at=now() WHERE id=v_snag.id RETURNING * INTO v_snag;
  INSERT INTO public.snag_events(snag_id,project_id,actor_id,event_type,previous_state,new_state,source_command_id)
  VALUES(v_snag.id,v_snag.project_id,v_uid,'SNAG_EVIDENCE_ADDED',jsonb_build_object('status',v_snag.status),jsonb_build_object('status',v_snag.status,'evidenceId',v_intent.id,'evidenceType',v_intent.evidence_type,'filename',v_intent.original_filename),p_request_id) RETURNING id INTO v_event_id;
  INSERT INTO public.snag_evidence(id,project_id,snag_id,evidence_type,storage_path,original_filename,mime_type,byte_size,note,created_by,transition_event_id,client_request_id,capture_timestamp,checksum,evidence_sequence)
  VALUES(v_intent.id,v_intent.project_id,v_intent.snag_id,v_intent.evidence_type,v_intent.storage_path,v_intent.original_filename,v_intent.mime_type,v_intent.byte_size,v_intent.note,v_uid,v_event_id,v_intent.client_request_id,v_intent.capture_timestamp,v_intent.checksum,(SELECT coalesce(max(evidence_sequence),0)+1 FROM public.snag_evidence WHERE snag_id=v_intent.snag_id)) RETURNING * INTO v_evidence;
  UPDATE public.snag_evidence_upload_intents SET registered_at=now() WHERE id=v_intent.id;
  RETURN jsonb_build_object('evidence',to_jsonb(v_evidence),'snag',to_jsonb(v_snag),'eventId',v_event_id,'idempotentReplay',false);
END $$;

CREATE OR REPLACE FUNCTION public.get_snag_evidence_policy(p_project_id bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
  IF auth.uid() IS NULL OR NOT public.can_access_project(p_project_id) THEN RAISE EXCEPTION 'EVIDENCE_ACCESS_DENIED' USING ERRCODE='42501'; END IF;
  RETURN '{"schemaVersion":1,"allowedMimeTypes":["image/jpeg","image/png","image/webp"],"maxFileBytes":8388608,"maxFileMegabytes":8,"maxEvidenceCount":20,"evidenceTypes":["CONDITION","CORRECTION","VERIFICATION","GENERAL"],"correctionRequiredForReview":false,"verificationRequiredForClosure":false,"noteCanSatisfyRequirement":false,"requiredEvidenceCount":0}'::jsonb;
END $$;

CREATE OR REPLACE FUNCTION public.get_snag_closeout(p_project_id bigint,p_snag_id uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_result jsonb; BEGIN
  IF auth.uid() IS NULL OR NOT public.can_access_project(p_project_id) THEN RAISE EXCEPTION 'EVIDENCE_ACCESS_DENIED' USING ERRCODE='42501'; END IF;
  SELECT jsonb_build_object('schemaVersion',1,'project',jsonb_build_object('id',p.id,'name',coalesce(p.store_code,'[missing]')),'snag',to_jsonb(s)-'project_id','plan',CASE WHEN pv.id IS NULL THEN NULL ELSE jsonb_build_object('id',pv.id,'name',pv.name,'revision',pv.version,'pageNumber',s.plan_page_number,'x',s.plan_x,'y',s.plan_y) END,'timeline',coalesce((SELECT jsonb_agg(to_jsonb(ev) ORDER BY ev.occurred_at,ev.id) FROM public.snag_events ev WHERE ev.snag_id=s.id),'[]'::jsonb),'evidence',coalesce((SELECT jsonb_agg(to_jsonb(e)-'storage_path' ORDER BY e.evidence_type,e.created_at,e.id) FROM public.snag_evidence e WHERE e.snag_id=s.id),'[]'::jsonb),'missing',jsonb_build_array()) INTO v_result
  FROM public.snags s JOIN public.projects p ON p.id=s.project_id LEFT JOIN public.snag_plan_versions pv ON pv.id=s.plan_version_id WHERE s.id=p_snag_id AND s.project_id=p_project_id;
  IF v_result IS NULL THEN RAISE EXCEPTION 'SNAG_NOT_FOUND' USING ERRCODE='P0002'; END IF; RETURN v_result;
END $$;

CREATE OR REPLACE FUNCTION public.prevent_registered_snag_evidence_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$
BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'SNAG_EVIDENCE_IMMUTABLE' USING ERRCODE='55000'; END IF;
  IF OLD.transition_event_id IS NULL AND NEW.transition_event_id IS NOT NULL AND (to_jsonb(NEW)-'transition_event_id')=(to_jsonb(OLD)-'transition_event_id') THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'SNAG_EVIDENCE_IMMUTABLE' USING ERRCODE='55000'; END $$;
CREATE TRIGGER snag_evidence_immutable BEFORE UPDATE OR DELETE ON public.snag_evidence FOR EACH ROW EXECUTE FUNCTION public.prevent_registered_snag_evidence_mutation();

REVOKE ALL ON FUNCTION public.authorize_snag_evidence_upload(bigint,uuid,uuid,uuid,integer,jsonb),public.register_snag_evidence(uuid),public.get_snag_evidence_policy(bigint),public.get_snag_closeout(bigint,uuid),public.prevent_registered_snag_evidence_mutation() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.authorize_snag_evidence_upload(bigint,uuid,uuid,uuid,integer,jsonb),public.register_snag_evidence(uuid),public.get_snag_evidence_policy(bigint),public.get_snag_closeout(bigint,uuid) TO authenticated;

-- MIGRATION 035_snag_canonical_field_capture.sql SHA256 0d02ee77c6001a2369c159b50350e45e23d6f1942ed0a4672b19699fee3bd52a
-- Phase 5: canonical field capture, independent publication state, trades and stakeholders.

CREATE TABLE public.project_snag_sequences (
  project_id bigint PRIMARY KEY REFERENCES public.projects(id) ON DELETE CASCADE,
  last_number integer NOT NULL DEFAULT 0 CHECK (last_number >= 0)
);
INSERT INTO public.project_snag_sequences(project_id,last_number)
SELECT project_id,max(snag_number) FROM public.snags GROUP BY project_id ON CONFLICT DO NOTHING;

CREATE TABLE public.project_snag_trades (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id bigint NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,
  code text NOT NULL, name text NOT NULL CHECK (btrim(name)<>''), color text NOT NULL DEFAULT '#2563EB' CHECK (color ~ '^#[0-9A-Fa-f]{6}$'),
  is_active boolean NOT NULL DEFAULT true, created_by uuid NOT NULL REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(project_id,code), UNIQUE(project_id,name)
);
CREATE TABLE public.project_stakeholders (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id bigint NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,
  company_name text NOT NULL CHECK (btrim(company_name)<>''), project_role text NOT NULL DEFAULT '', contact_name text,
  email text, user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, is_active boolean NOT NULL DEFAULT true,
  created_by uuid NOT NULL REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.snag_trade_stakeholders (
  trade_id uuid NOT NULL REFERENCES public.project_snag_trades(id) ON DELETE CASCADE,
  stakeholder_id uuid NOT NULL REFERENCES public.project_stakeholders(id) ON DELETE CASCADE,
  is_preferred boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(trade_id,stakeholder_id)
);
CREATE UNIQUE INDEX snag_trade_one_preferred ON public.snag_trade_stakeholders(trade_id) WHERE is_preferred;

ALTER TABLE public.snags
  ADD COLUMN publication_state text NOT NULL DEFAULT 'PUBLISHED' CHECK (publication_state IN ('CAPTURED','PUBLISHED','ARCHIVED')),
  ADD COLUMN trade_id uuid REFERENCES public.project_snag_trades(id) ON DELETE RESTRICT,
  ADD COLUMN stakeholder_id uuid REFERENCES public.project_stakeholders(id) ON DELETE RESTRICT,
  ADD COLUMN published_at timestamptz,
  ADD COLUMN published_by uuid REFERENCES auth.users(id),
  ADD COLUMN archived_at timestamptz,
  ADD COLUMN archived_by uuid REFERENCES auth.users(id),
  ADD COLUMN archive_reason text;
UPDATE public.snags SET published_at=created_at,published_by=created_by WHERE publication_state='PUBLISHED';
ALTER TABLE public.snags ADD CONSTRAINT snags_publication_timestamps CHECK (
  (publication_state='CAPTURED' AND published_at IS NULL AND archived_at IS NULL)
  OR (publication_state='PUBLISHED' AND published_at IS NOT NULL AND archived_at IS NULL)
  OR (publication_state='ARCHIVED' AND archived_at IS NOT NULL)
);
CREATE OR REPLACE FUNCTION public.normalize_snag_publication_timestamps() RETURNS trigger
LANGUAGE plpgsql SET search_path=public,pg_temp AS $$
BEGIN
  IF TG_OP='INSERT' AND NEW.snag_number IS NOT NULL THEN
    INSERT INTO public.project_snag_sequences(project_id,last_number) VALUES(NEW.project_id,NEW.snag_number)
    ON CONFLICT(project_id) DO UPDATE SET last_number=greatest(public.project_snag_sequences.last_number,EXCLUDED.last_number);
  END IF;
  IF NEW.publication_state='PUBLISHED' THEN NEW.published_at:=coalesce(NEW.published_at,NEW.created_at,now());NEW.published_by:=coalesce(NEW.published_by,NEW.created_by);
  ELSIF NEW.publication_state='CAPTURED' THEN NEW.published_at:=NULL;NEW.published_by:=NULL;NEW.archived_at:=NULL;NEW.archived_by:=NULL;END IF;RETURN NEW;
END $$;
CREATE TRIGGER snags_normalize_publication BEFORE INSERT OR UPDATE OF publication_state ON public.snags FOR EACH ROW EXECUTE FUNCTION public.normalize_snag_publication_timestamps();
CREATE INDEX idx_snags_project_publication ON public.snags(project_id,publication_state,updated_at DESC);

CREATE TABLE public.snag_comments (
  id bigserial PRIMARY KEY, snag_id uuid NOT NULL REFERENCES public.snags(id) ON DELETE RESTRICT,
  project_id bigint NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE, body text NOT NULL CHECK (btrim(body)<>''),
  actor_id uuid NOT NULL REFERENCES auth.users(id), source_command_id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(actor_id,source_command_id)
);

ALTER TABLE public.project_snag_sequences ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.project_snag_trades ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.project_stakeholders ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.snag_trade_stakeholders ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.snag_comments ENABLE ROW LEVEL SECURITY;
CREATE POLICY snag_trades_select ON public.project_snag_trades FOR SELECT TO authenticated USING (public.can_access_project(project_id));
CREATE POLICY project_stakeholders_select ON public.project_stakeholders FOR SELECT TO authenticated USING (public.can_access_project(project_id));
CREATE POLICY snag_trade_stakeholders_select ON public.snag_trade_stakeholders FOR SELECT TO authenticated USING (
  EXISTS(SELECT 1 FROM public.project_snag_trades t WHERE t.id=trade_id AND public.can_access_project(t.project_id))
);
CREATE POLICY snag_comments_select ON public.snag_comments FOR SELECT TO authenticated USING (
  EXISTS(SELECT 1 FROM public.snags s WHERE s.id=snag_id AND s.project_id=project_id AND public.can_access_project(project_id)
    AND (lower((SELECT role FROM public.profiles WHERE id=auth.uid()))<>'contractor' OR (s.publication_state='PUBLISHED' AND s.assignee_id=auth.uid())))
);

DROP POLICY snags_select ON public.snags;
CREATE POLICY snags_select ON public.snags FOR SELECT TO authenticated USING (
  public.can_access_project(project_id) AND (
    lower((SELECT role FROM public.profiles WHERE id=auth.uid()))<>'contractor'
    OR (publication_state='PUBLISHED' AND assignee_id=auth.uid())
  )
);
DROP POLICY snag_events_select ON public.snag_events;
CREATE POLICY snag_events_select ON public.snag_events FOR SELECT TO authenticated USING (
  public.can_access_project(project_id) AND EXISTS(SELECT 1 FROM public.snags s WHERE s.id=snag_id AND
    (lower((SELECT role FROM public.profiles WHERE id=auth.uid()))<>'contractor' OR (s.publication_state='PUBLISHED' AND s.assignee_id=auth.uid())))
);
DROP POLICY snag_evidence_select ON public.snag_evidence;
CREATE POLICY snag_evidence_select ON public.snag_evidence FOR SELECT TO authenticated USING (
  EXISTS(SELECT 1 FROM public.snags s WHERE s.id=snag_id AND public.can_access_project(s.project_id) AND
    (lower((SELECT role FROM public.profiles WHERE id=auth.uid()))<>'contractor' OR (s.publication_state='PUBLISHED' AND s.assignee_id=auth.uid())))
);

REVOKE ALL ON public.project_snag_sequences,public.project_snag_trades,public.project_stakeholders,public.snag_trade_stakeholders,public.snag_comments FROM anon,authenticated;
GRANT SELECT ON public.project_snag_trades,public.project_stakeholders,public.snag_trade_stakeholders,public.snag_comments TO authenticated;
REVOKE ALL ON SEQUENCE public.snag_comments_id_seq FROM anon,authenticated;
GRANT USAGE,SELECT ON SEQUENCE public.snag_comments_id_seq TO service_role;

CREATE OR REPLACE FUNCTION public.next_snag_number(p_project_id bigint) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_number integer;
BEGIN
  INSERT INTO public.project_snag_sequences(project_id,last_number) VALUES(p_project_id,1)
  ON CONFLICT(project_id) DO UPDATE SET last_number=project_snag_sequences.last_number+1
  RETURNING last_number INTO v_number; RETURN v_number;
END $$;

CREATE OR REPLACE FUNCTION public.capture_snag_observation(p_project_id bigint,p_plan_id uuid,p_page integer,p_x numeric,p_y numeric,p_client_request_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_uid uuid:=auth.uid();v_role text;v_req public.snag_command_requests%ROWTYPE;v_plan public.snag_plan_versions%ROWTYPE;v_snag public.snags%ROWTYPE;v_number integer;v_event bigint;v_response jsonb;v_command jsonb;v_inserted integer;
BEGIN
  SELECT upper(role) INTO v_role FROM public.profiles WHERE id=v_uid;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE='28000'; END IF;
  IF v_role NOT IN ('ADMIN','PM') OR NOT public.can_write_project(p_project_id) THEN RAISE EXCEPTION 'COMMAND_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF p_x NOT BETWEEN 0 AND 1 OR p_y NOT BETWEEN 0 AND 1 THEN RAISE EXCEPTION 'INVALID_PLAN_COORDINATES' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_plan FROM public.snag_plan_versions WHERE id=p_plan_id AND project_id=p_project_id AND p_page BETWEEN 1 AND page_count;
  IF NOT FOUND THEN RAISE EXCEPTION 'PLAN_PROJECT_MISMATCH' USING ERRCODE='23514'; END IF;
  p_x:=round(p_x,6);p_y:=round(p_y,6);
  v_command:=jsonb_build_object('type','captureObservation','projectId',p_project_id,'planId',p_plan_id,'page',p_page,'x',p_x,'y',p_y);
  INSERT INTO public.snag_command_requests(actor_id,client_request_id,project_id,command_type,request_payload)
  VALUES(v_uid,p_client_request_id,p_project_id,'captureObservation',v_command) ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_inserted=ROW_COUNT;
  SELECT * INTO v_req FROM public.snag_command_requests WHERE actor_id=v_uid AND client_request_id=p_client_request_id FOR UPDATE;
  IF v_req.response IS NOT NULL THEN RETURN v_req.response||jsonb_build_object('idempotentReplay',true); END IF;
  IF v_inserted=0 AND v_req.request_payload IS DISTINCT FROM v_command THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT' USING ERRCODE='23505'; END IF;
  v_number:=public.next_snag_number(p_project_id);
  INSERT INTO public.snags(project_id,snag_number,title,category_code,discipline_code,priority,status,location_text,plan_version_id,plan_page_number,plan_x,plan_y,created_by,publication_state)
  VALUES(p_project_id,v_number,'Observation #'||v_number,'GENERAL','GENERAL','MEDIUM','OPEN','Plan page '||p_page,p_plan_id,p_page,p_x,p_y,v_uid,'CAPTURED') RETURNING * INTO v_snag;
  INSERT INTO public.snag_events(snag_id,project_id,actor_id,event_type,new_state,source_command_id)
  VALUES(v_snag.id,p_project_id,v_uid,'SNAG_CAPTURED',to_jsonb(v_snag),p_client_request_id) RETURNING id INTO v_event;
  v_response:=jsonb_build_object('snag',to_jsonb(v_snag),'eventId',v_event,'idempotentReplay',false);
  UPDATE public.snag_command_requests SET response=v_response,completed_at=now() WHERE actor_id=v_uid AND client_request_id=p_client_request_id;
  RETURN v_response;
END $$;

CREATE OR REPLACE FUNCTION public.execute_snag_product_command(p_command jsonb,p_client_request_id uuid,p_expected_version integer DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_uid uuid:=auth.uid();v_role text;v_type text:=p_command->>'type';v_project bigint:=(p_command->>'projectId')::bigint;v_id uuid:=nullif(p_command->>'snagId','')::uuid;v_payload jsonb:=coalesce(p_command->'payload','{}');v_req public.snag_command_requests%ROWTYPE;v_snag public.snags%ROWTYPE;v_copy public.snags%ROWTYPE;v_trade public.project_snag_trades%ROWTYPE;v_stake public.project_stakeholders%ROWTYPE;v_event bigint;v_response jsonb;v_number integer;v_assignee uuid;
BEGIN
  SELECT upper(role) INTO v_role FROM public.profiles WHERE id=v_uid;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE='28000'; END IF;
  IF v_role NOT IN ('ADMIN','PM') OR NOT public.can_write_project(v_project) THEN RAISE EXCEPTION 'COMMAND_FORBIDDEN' USING ERRCODE='42501'; END IF;
  INSERT INTO public.snag_command_requests(actor_id,client_request_id,project_id,command_type,request_payload) VALUES(v_uid,p_client_request_id,v_project,v_type,p_command) ON CONFLICT DO NOTHING;
  SELECT * INTO v_req FROM public.snag_command_requests WHERE actor_id=v_uid AND client_request_id=p_client_request_id FOR UPDATE;
  IF v_req.request_payload<>p_command THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT' USING ERRCODE='23505'; END IF;
  IF v_req.response IS NOT NULL THEN RETURN v_req.response||jsonb_build_object('idempotentReplay',true); END IF;
  SELECT * INTO v_snag FROM public.snags WHERE id=v_id AND project_id=v_project FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'SNAG_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF p_expected_version IS DISTINCT FROM v_snag.version THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001'; END IF;
  IF v_type='completeCapture' AND v_snag.publication_state='CAPTURED' THEN
    IF v_payload?'tradeId' THEN SELECT * INTO v_trade FROM public.project_snag_trades WHERE id=(v_payload->>'tradeId')::uuid AND project_id=v_project AND is_active; IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_TRADE' USING ERRCODE='22023'; END IF; END IF;
    IF v_payload?'stakeholderId' THEN SELECT * INTO v_stake FROM public.project_stakeholders WHERE id=(v_payload->>'stakeholderId')::uuid AND project_id=v_project AND is_active; IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_STAKEHOLDER' USING ERRCODE='22023'; END IF; END IF;
    UPDATE public.snags SET title=coalesce(nullif(btrim(v_payload->>'title'),''),title),description=coalesce(v_payload->>'description',description),trade_id=v_trade.id,stakeholder_id=v_stake.id,assignee_id=v_stake.user_id,
      discipline_code=coalesce(v_trade.code,discipline_code),priority=coalesce(v_payload->>'priority',priority),due_date=nullif(v_payload->>'dueDate','')::date,version=version+1,updated_at=now() WHERE id=v_id RETURNING * INTO v_snag;
    INSERT INTO public.snag_events(snag_id,project_id,actor_id,event_type,new_state,source_command_id) VALUES(v_id,v_project,v_uid,'SNAG_CAPTURE_COMPLETED',to_jsonb(v_snag),p_client_request_id) RETURNING id INTO v_event;
  ELSIF v_type='publishObservation' AND v_snag.publication_state='CAPTURED' THEN
    IF v_snag.trade_id IS NULL OR v_snag.stakeholder_id IS NULL OR (btrim(v_snag.description)='' AND NOT EXISTS(SELECT 1 FROM public.snag_evidence e WHERE e.snag_id=v_id)) THEN RAISE EXCEPTION 'OBSERVATION_NEEDS_DETAILS' USING ERRCODE='22023'; END IF;
    SELECT user_id INTO v_assignee FROM public.project_stakeholders WHERE id=v_snag.stakeholder_id;
    UPDATE public.snags SET publication_state='PUBLISHED',published_at=now(),published_by=v_uid,assignee_id=v_assignee,status=CASE WHEN v_assignee IS NULL THEN 'OPEN' ELSE 'ASSIGNED' END,version=version+1,updated_at=now() WHERE id=v_id RETURNING * INTO v_snag;
    INSERT INTO public.snag_events(snag_id,project_id,actor_id,event_type,new_state,source_command_id) VALUES(v_id,v_project,v_uid,'SNAG_PUBLISHED',to_jsonb(v_snag),p_client_request_id) RETURNING id INTO v_event;
  ELSIF v_type='archiveObservation' AND v_snag.publication_state<>'ARCHIVED' THEN
    IF btrim(coalesce(v_payload->>'reason',''))='' THEN RAISE EXCEPTION 'ARCHIVE_REASON_REQUIRED' USING ERRCODE='22023'; END IF;
    UPDATE public.snags SET publication_state='ARCHIVED',archived_at=now(),archived_by=v_uid,archive_reason=btrim(v_payload->>'reason'),version=version+1,updated_at=now() WHERE id=v_id RETURNING * INTO v_snag;
    INSERT INTO public.snag_events(snag_id,project_id,actor_id,event_type,new_state,reason,source_command_id) VALUES(v_id,v_project,v_uid,'SNAG_ARCHIVED',to_jsonb(v_snag),v_payload->>'reason',p_client_request_id) RETURNING id INTO v_event;
  ELSIF v_type='duplicateObservation' THEN
    v_number:=public.next_snag_number(v_project);
    INSERT INTO public.snags(project_id,snag_number,title,description,category_code,discipline_code,priority,status,due_date,location_zone_id,location_level,location_room,location_text,plan_version_id,plan_page_number,plan_x,plan_y,created_by,publication_state,trade_id,stakeholder_id)
    VALUES(v_project,v_number,v_snag.title,v_snag.description,v_snag.category_code,v_snag.discipline_code,v_snag.priority,'OPEN',v_snag.due_date,v_snag.location_zone_id,v_snag.location_level,v_snag.location_room,v_snag.location_text,v_snag.plan_version_id,v_snag.plan_page_number,v_snag.plan_x,v_snag.plan_y,v_uid,'CAPTURED',v_snag.trade_id,v_snag.stakeholder_id) RETURNING * INTO v_copy;
    INSERT INTO public.snag_events(snag_id,project_id,actor_id,event_type,new_state,source_command_id) VALUES(v_copy.id,v_project,v_uid,'SNAG_DUPLICATED',jsonb_build_object('sourceSnagId',v_id,'snag',to_jsonb(v_copy)),p_client_request_id) RETURNING id INTO v_event;v_snag:=v_copy;
  ELSE RAISE EXCEPTION 'INVALID_PRODUCT_COMMAND' USING ERRCODE='22023'; END IF;
  v_response:=jsonb_build_object('snag',to_jsonb(v_snag),'eventId',v_event,'idempotentReplay',false);
  UPDATE public.snag_command_requests SET response=v_response,completed_at=now() WHERE actor_id=v_uid AND client_request_id=p_client_request_id;RETURN v_response;
END $$;

CREATE OR REPLACE FUNCTION public.publish_snag_observations(p_project_id bigint,p_snag_ids uuid[],p_client_request_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_uid uuid:=auth.uid();v_role text;v_req public.snag_command_requests%ROWTYPE;v_command jsonb;v_row public.snags%ROWTYPE;v_valid uuid[]:='{}';v_invalid uuid[]:='{}';v_event uuid;
BEGIN
  SELECT upper(role) INTO v_role FROM public.profiles WHERE id=v_uid;
  IF v_role NOT IN ('ADMIN','PM') OR NOT public.can_write_project(p_project_id) THEN RAISE EXCEPTION 'COMMAND_FORBIDDEN' USING ERRCODE='42501'; END IF;
  v_command:=jsonb_build_object('type','batchPublish','projectId',p_project_id,'snagIds',to_jsonb(p_snag_ids));
  INSERT INTO public.snag_command_requests(actor_id,client_request_id,project_id,command_type,request_payload) VALUES(v_uid,p_client_request_id,p_project_id,'batchPublish',v_command) ON CONFLICT DO NOTHING;
  SELECT * INTO v_req FROM public.snag_command_requests WHERE actor_id=v_uid AND client_request_id=p_client_request_id FOR UPDATE;
  IF v_req.request_payload<>v_command THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT' USING ERRCODE='23505'; END IF;
  IF v_req.response IS NOT NULL THEN RETURN v_req.response||jsonb_build_object('idempotentReplay',true); END IF;
  FOR v_row IN SELECT * FROM public.snags WHERE project_id=p_project_id AND id=ANY(p_snag_ids) ORDER BY snag_number FOR UPDATE LOOP
    IF v_row.publication_state='CAPTURED' AND v_row.trade_id IS NOT NULL AND v_row.stakeholder_id IS NOT NULL AND (btrim(v_row.description)<>'' OR EXISTS(SELECT 1 FROM public.snag_evidence e WHERE e.snag_id=v_row.id)) THEN
      UPDATE public.snags s SET publication_state='PUBLISHED',published_at=now(),published_by=v_uid,assignee_id=ps.user_id,status=CASE WHEN ps.user_id IS NULL THEN 'OPEN' ELSE 'ASSIGNED' END,version=s.version+1,updated_at=now() FROM public.project_stakeholders ps WHERE s.id=v_row.id AND ps.id=s.stakeholder_id;
      v_event:=gen_random_uuid();INSERT INTO public.snag_events(snag_id,project_id,actor_id,event_type,new_state,source_command_id) SELECT id,project_id,v_uid,'SNAG_PUBLISHED',to_jsonb(s),v_event FROM public.snags s WHERE id=v_row.id;v_valid:=array_append(v_valid,v_row.id);
    ELSE v_invalid:=array_append(v_invalid,v_row.id); END IF;
  END LOOP;
  UPDATE public.snag_command_requests SET response=jsonb_build_object('published',v_valid,'needsDetails',v_invalid,'idempotentReplay',false),completed_at=now() WHERE actor_id=v_uid AND client_request_id=p_client_request_id;
  RETURN jsonb_build_object('published',v_valid,'needsDetails',v_invalid,'idempotentReplay',false);
END $$;

CREATE OR REPLACE FUNCTION public.add_snag_comment(p_project_id bigint,p_snag_id uuid,p_body text,p_client_request_id uuid)
RETURNS public.snag_comments LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_uid uuid:=auth.uid();v_role text;v_snag public.snags%ROWTYPE;v_comment public.snag_comments%ROWTYPE;
BEGIN
  SELECT upper(role) INTO v_role FROM public.profiles WHERE id=v_uid;SELECT * INTO v_snag FROM public.snags WHERE id=p_snag_id AND project_id=p_project_id;
  IF NOT FOUND OR NOT public.can_access_project(p_project_id) THEN RAISE EXCEPTION 'PROJECT_ACCESS_DENIED' USING ERRCODE='42501'; END IF;
  IF v_role='CONTRACTOR' AND (v_snag.publication_state<>'PUBLISHED' OR v_snag.assignee_id<>v_uid) THEN RAISE EXCEPTION 'COMMAND_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF v_role='VIEWER' OR btrim(coalesce(p_body,''))='' THEN RAISE EXCEPTION 'COMMAND_FORBIDDEN' USING ERRCODE='42501'; END IF;
  INSERT INTO public.snag_comments(snag_id,project_id,body,actor_id,source_command_id) VALUES(p_snag_id,p_project_id,btrim(p_body),v_uid,p_client_request_id) ON CONFLICT(actor_id,source_command_id) DO UPDATE SET body=snag_comments.body RETURNING * INTO v_comment;
  INSERT INTO public.snag_events(snag_id,project_id,actor_id,event_type,new_state,source_command_id) VALUES(p_snag_id,p_project_id,v_uid,'SNAG_COMMENT_ADDED',jsonb_build_object('commentId',v_comment.id),gen_random_uuid());RETURN v_comment;
END $$;

CREATE OR REPLACE FUNCTION public.configure_snag_catalog(p_project_id bigint,p_action text,p_payload jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_uid uuid:=auth.uid();v_role text;v_trade public.project_snag_trades%ROWTYPE;v_stake public.project_stakeholders%ROWTYPE;
BEGIN
  SELECT upper(role) INTO v_role FROM public.profiles WHERE id=v_uid;
  IF v_role NOT IN ('ADMIN','PM') OR NOT public.can_write_project(p_project_id) THEN RAISE EXCEPTION 'COMMAND_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF p_action='CREATE_TRADE' THEN
    INSERT INTO public.project_snag_trades(project_id,code,name,color,created_by) VALUES(p_project_id,upper(regexp_replace(btrim(p_payload->>'name'),'[^a-zA-Z0-9]+','_','g')),btrim(p_payload->>'name'),coalesce(p_payload->>'color','#2563EB'),v_uid) RETURNING * INTO v_trade;RETURN to_jsonb(v_trade);
  ELSIF p_action='CREATE_STAKEHOLDER' THEN
    INSERT INTO public.project_stakeholders(project_id,company_name,project_role,contact_name,email,user_id,created_by) VALUES(p_project_id,btrim(p_payload->>'companyName'),coalesce(p_payload->>'projectRole',''),nullif(btrim(p_payload->>'contactName'),''),nullif(lower(btrim(p_payload->>'email')),''),nullif(p_payload->>'userId','')::uuid,v_uid) RETURNING * INTO v_stake;RETURN to_jsonb(v_stake);
  ELSIF p_action='MAP_STAKEHOLDER' THEN
    SELECT * INTO v_trade FROM public.project_snag_trades WHERE id=(p_payload->>'tradeId')::uuid AND project_id=p_project_id;
    SELECT * INTO v_stake FROM public.project_stakeholders WHERE id=(p_payload->>'stakeholderId')::uuid AND project_id=p_project_id;
    IF v_trade.id IS NULL OR v_stake.id IS NULL THEN RAISE EXCEPTION 'CATALOG_PROJECT_MISMATCH' USING ERRCODE='23514'; END IF;
    IF coalesce((p_payload->>'preferred')::boolean,false) THEN UPDATE public.snag_trade_stakeholders SET is_preferred=false WHERE trade_id=v_trade.id; END IF;
    INSERT INTO public.snag_trade_stakeholders(trade_id,stakeholder_id,is_preferred) VALUES(v_trade.id,v_stake.id,coalesce((p_payload->>'preferred')::boolean,false)) ON CONFLICT(trade_id,stakeholder_id) DO UPDATE SET is_preferred=excluded.is_preferred;RETURN jsonb_build_object('tradeId',v_trade.id,'stakeholderId',v_stake.id);
  ELSE RAISE EXCEPTION 'INVALID_CATALOG_ACTION' USING ERRCODE='22023'; END IF;
END $$;

REVOKE ALL ON FUNCTION public.normalize_snag_publication_timestamps(),public.next_snag_number(bigint),public.capture_snag_observation(bigint,uuid,integer,numeric,numeric,uuid),public.execute_snag_product_command(jsonb,uuid,integer),public.publish_snag_observations(bigint,uuid[],uuid),public.add_snag_comment(bigint,uuid,text,uuid),public.configure_snag_catalog(bigint,text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.capture_snag_observation(bigint,uuid,integer,numeric,numeric,uuid),public.execute_snag_product_command(jsonb,uuid,integer),public.publish_snag_observations(bigint,uuid[],uuid),public.add_snag_comment(bigint,uuid,text,uuid),public.configure_snag_catalog(bigint,text,jsonb) TO authenticated;

