CREATE OR REPLACE FUNCTION public.submit_contractor_schedule(
  p_project_id bigint,
  p_client_request_id uuid,
  p_contractor_comment text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_role text;
  v_assigned_projects integer[] := '{}'::integer[];
  v_schedule_mode text;
  v_template_id uuid;
  v_lifecycle_status text;
  v_request public.write_command_requests%ROWTYPE;
  v_version_id bigint;
  v_submission_number integer;
  v_scope_count integer;
  v_incomplete_count integer;
  v_execution_scope_version_id bigint;
  v_ontology_version_id uuid;
  v_execution_scope_work_group_count integer;
  v_snapshot_work_group_count integer;
  v_result jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF p_client_request_id IS NULL THEN
    RAISE EXCEPTION 'client_request_id is required' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.write_command_requests(actor_id, operation, client_request_id, project_id)
  VALUES (v_uid, 'schedule.submit', p_client_request_id, p_project_id)
  ON CONFLICT (actor_id, operation, client_request_id) DO NOTHING;

  SELECT * INTO v_request
  FROM public.write_command_requests
  WHERE actor_id = v_uid
    AND operation = 'schedule.submit'
    AND client_request_id = p_client_request_id;

  IF v_request.project_id <> p_project_id THEN
    RAISE EXCEPTION 'Idempotency key belongs to another project' USING ERRCODE = '23505';
  END IF;
  IF v_request.response IS NOT NULL THEN
    RETURN v_request.response || jsonb_build_object('idempotentReplay', true);
  END IF;

  SELECT schedule_ownership_mode, template_id
    INTO v_schedule_mode, v_template_id
  FROM public.projects
  WHERE id = p_project_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Project % not found', p_project_id USING ERRCODE = 'P0002';
  END IF;

  SELECT lower(role), COALESCE(assigned_projects, '{}'::integer[])
    INTO v_role, v_assigned_projects
  FROM public.profiles
  WHERE id = v_uid;

  IF v_role IS DISTINCT FROM 'contractor'
    OR NOT (p_project_id = ANY(v_assigned_projects::bigint[])) THEN
    RAISE EXCEPTION 'Not authorized for this project schedule' USING ERRCODE = '42501';
  END IF;

  IF v_schedule_mode <> 'CONTRACTOR_MANAGED' THEN
    RAISE EXCEPTION 'SCHEDULE_NOT_CONTRACTOR_MANAGED: project schedule is not contractor-managed'
      USING ERRCODE = '42501';
  END IF;

  v_lifecycle_status := public.contractor_schedule_lifecycle_status(p_project_id);
  IF v_lifecycle_status = 'PENDING_REVIEW' THEN
    RAISE EXCEPTION 'SCHEDULE_PENDING_REVIEW: a schedule submission is already pending review'
      USING ERRCODE = '55000';
  END IF;
  IF v_lifecycle_status = 'APPROVED' THEN
    RAISE EXCEPTION 'BASELINE_ALREADY_APPROVED: an approved baseline already exists for this project'
      USING ERRCODE = '55000';
  END IF;

  SELECT count(*) INTO v_scope_count
  FROM public.project_gantt_tasks
  WHERE project_id = p_project_id AND NOT COALESCE(is_archived, false);

  IF v_scope_count = 0 THEN
    RAISE EXCEPTION 'EMPTY_SCOPE: no active Scope work packages exist for this project'
      USING ERRCODE = '22023';
  END IF;

  SELECT count(*) INTO v_incomplete_count
  FROM public.project_gantt_tasks
  WHERE project_id = p_project_id
    AND NOT COALESCE(is_archived, false)
    AND (planned_start IS NULL OR planned_end IS NULL OR duration_days IS NULL);

  IF v_incomplete_count > 0 THEN
    RAISE EXCEPTION 'SCHEDULE_INCOMPLETE: % of % active work packages are missing Start/Finish',
      v_incomplete_count, v_scope_count USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.project_gantt_tasks
    WHERE project_id = p_project_id
      AND NOT COALESCE(is_archived, false)
      AND planned_start > planned_end
  ) THEN
    RAISE EXCEPTION 'INVALID_SCHEDULE_DATES: one or more work packages have Start after Finish'
      USING ERRCODE = '22023';
  END IF;

  SELECT scope.id, scope.ontology_version_id
    INTO v_execution_scope_version_id, v_ontology_version_id
  FROM public.project_execution_scope_versions scope
  WHERE scope.project_id = p_project_id
  ORDER BY scope.revision_number DESC
  LIMIT 1;

  -- Canonical projects must submit the current complete Activity model. A
  -- partially linked or stale Gantt is never silently accepted as baseline.
  IF v_execution_scope_version_id IS NOT NULL THEN
    IF EXISTS (
      SELECT 1
      FROM public.project_gantt_tasks task
      LEFT JOIN public.project_schedule_activities activity
        ON activity.id = task.schedule_activity_id
       AND activity.project_id = task.project_id
       AND activity.execution_scope_version_id = v_execution_scope_version_id
       AND NOT activity.is_archived
      WHERE task.project_id = p_project_id
        AND NOT COALESCE(task.is_archived, false)
        AND activity.id IS NULL
    ) THEN
      RAISE EXCEPTION 'SCHEDULE_SETUP_STALE: every active Gantt row must reference an active Schedule Activity in the current Execution Scope'
        USING ERRCODE = '55000';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.project_schedule_activities activity
      LEFT JOIN public.project_gantt_tasks task
        ON task.project_id = activity.project_id
       AND task.schedule_activity_id = activity.id
       AND NOT COALESCE(task.is_archived, false)
      WHERE activity.project_id = p_project_id
        AND activity.execution_scope_version_id = v_execution_scope_version_id
        AND NOT activity.is_archived
        AND task.id IS NULL
    ) THEN
      RAISE EXCEPTION 'SCHEDULE_SETUP_INCOMPLETE: every active Schedule Activity must have one active Gantt row'
        USING ERRCODE = '55000';
    END IF;

    SELECT count(*) INTO v_execution_scope_work_group_count
    FROM public.project_execution_scope_items item
    WHERE item.execution_scope_version_id = v_execution_scope_version_id;

    SELECT count(DISTINCT mapping.work_group_id) INTO v_snapshot_work_group_count
    FROM public.project_schedule_activity_work_groups mapping
    JOIN public.project_schedule_activities activity
      ON activity.id = mapping.activity_id
     AND activity.project_id = mapping.project_id
     AND NOT activity.is_archived
    WHERE mapping.project_id = p_project_id
      AND mapping.execution_scope_version_id = v_execution_scope_version_id;

    IF v_snapshot_work_group_count IS DISTINCT FROM v_execution_scope_work_group_count THEN
      RAISE EXCEPTION 'INCOMPLETE_EXECUTION_SCOPE_COVERAGE: Schedule Activities do not cover the current Execution Scope'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  SELECT COALESCE(max(submission_number), 0) + 1 INTO v_submission_number
  FROM public.project_schedule_versions
  WHERE project_id = p_project_id;

  INSERT INTO public.project_schedule_versions (
    project_id, submission_number, status, template_id,
    submitted_by, submitted_at, contractor_comment, submit_client_request_id,
    execution_scope_version_id
  ) VALUES (
    p_project_id, v_submission_number, 'PENDING_REVIEW', v_template_id,
    v_uid, now(), NULLIF(p_contractor_comment, ''), p_client_request_id,
    v_execution_scope_version_id
  )
  RETURNING id INTO v_version_id;

  IF v_execution_scope_version_id IS NULL THEN
    INSERT INTO public.project_schedule_version_tasks (
      version_id, wp_id, planned_start, planned_end, duration_days
    )
    SELECT v_version_id, wp_id, planned_start, planned_end, duration_days
    FROM public.project_gantt_tasks
    WHERE project_id = p_project_id AND NOT COALESCE(is_archived, false);
  ELSE
    INSERT INTO public.project_schedule_version_tasks (
      version_id, wp_id, planned_start, planned_end, duration_days,
      schedule_activity_id, activity_title, activity_phase_id,
      activity_phase_label
    )
    SELECT
      v_version_id,
      task.wp_id,
      task.planned_start,
      task.planned_end,
      task.duration_days,
      activity.id,
      activity.title,
      task.phase_id,
      task.phase_label
    FROM public.project_gantt_tasks task
    JOIN public.project_schedule_activities activity
      ON activity.id = task.schedule_activity_id
     AND activity.project_id = task.project_id
     AND activity.execution_scope_version_id = v_execution_scope_version_id
     AND NOT activity.is_archived
    WHERE task.project_id = p_project_id AND NOT COALESCE(task.is_archived, false);

    INSERT INTO public.project_schedule_version_activity_work_groups (
      version_id, schedule_activity_id, execution_scope_version_id,
      ontology_version_id, work_group_id
    )
    SELECT
      v_version_id,
      mapping.activity_id,
      mapping.execution_scope_version_id,
      mapping.ontology_version_id,
      mapping.work_group_id
    FROM public.project_schedule_activity_work_groups mapping
    JOIN public.project_schedule_activities activity
      ON activity.id = mapping.activity_id
     AND activity.project_id = mapping.project_id
     AND activity.execution_scope_version_id = mapping.execution_scope_version_id
     AND NOT activity.is_archived
    WHERE mapping.project_id = p_project_id
      AND mapping.execution_scope_version_id = v_execution_scope_version_id;
  END IF;

  v_result := jsonb_build_object(
    'submissionId', v_version_id,
    'projectId', p_project_id,
    'submissionNumber', v_submission_number,
    'status', 'PENDING_REVIEW',
    'scheduledCount', v_scope_count,
    'executionScopeVersionId', v_execution_scope_version_id
  );

  UPDATE public.write_command_requests
  SET response = v_result, completed_at = now()
  WHERE id = v_request.id;

  RETURN v_result || jsonb_build_object('idempotentReplay', false);
END;
$$;

REVOKE ALL ON FUNCTION public.submit_contractor_schedule(bigint, uuid, text)
  FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.submit_contractor_schedule(bigint, uuid, text)
  TO authenticated;

-- MIGRATION 066_pm_schedule_baseline_approval.sql SHA256 7205f93ced28546cf360a372550410782402ddd137fef184c8a87a4afe7a7116
-- 066_pm_schedule_baseline_approval.sql
-- Roadmap Phase B.10: PM approval creates an explicit, immutable official
-- baseline reference after validating the complete submitted Scope snapshot.

CREATE UNIQUE INDEX IF NOT EXISTS project_schedule_versions_id_project_uniq
  ON public.project_schedule_versions(id, project_id);

CREATE TABLE IF NOT EXISTS public.project_schedule_baselines (
  id bigserial PRIMARY KEY,
  project_id bigint NOT NULL REFERENCES public.projects(id) ON DELETE RESTRICT,
  schedule_version_id bigint NOT NULL UNIQUE,
  baseline_revision_number integer NOT NULL CHECK (baseline_revision_number > 0),
  execution_scope_version_id bigint,
  approved_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  approved_at timestamptz NOT NULL DEFAULT now(),
  pm_comment text,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (project_id, baseline_revision_number),
  FOREIGN KEY (schedule_version_id, project_id)
    REFERENCES public.project_schedule_versions(id, project_id) ON DELETE RESTRICT,
  FOREIGN KEY (schedule_version_id, execution_scope_version_id)
    REFERENCES public.project_schedule_versions(id, execution_scope_version_id) ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS project_schedule_baselines_project_idx
  ON public.project_schedule_baselines(project_id, baseline_revision_number DESC);

-- Preserve pre-066 approvals as official references without changing their
-- submitted or reviewed state. Canonical 065 rows carry their Scope pin;
-- older legacy rows remain explicitly scope-less.
INSERT INTO public.project_schedule_baselines (
  project_id, schedule_version_id, baseline_revision_number,
  execution_scope_version_id, approved_by, approved_at, pm_comment
)
SELECT
  version.project_id,
  version.id,
  version.baseline_revision_number,
  version.execution_scope_version_id,
  version.reviewed_by,
  version.reviewed_at,
  version.pm_comment
FROM public.project_schedule_versions version
WHERE version.status = 'APPROVED'
  AND version.baseline_revision_number IS NOT NULL
  AND version.reviewed_by IS NOT NULL
  AND version.reviewed_at IS NOT NULL
ON CONFLICT (schedule_version_id) DO NOTHING;

CREATE OR REPLACE FUNCTION private.prevent_schedule_baseline_mutation()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog
AS $$
BEGIN
  RAISE EXCEPTION 'SCHEDULE_BASELINE_IMMUTABLE' USING ERRCODE = '55000';
END;
$$;

DROP TRIGGER IF EXISTS project_schedule_baselines_immutable
  ON public.project_schedule_baselines;
CREATE TRIGGER project_schedule_baselines_immutable
  BEFORE UPDATE OR DELETE ON public.project_schedule_baselines
  FOR EACH ROW EXECUTE FUNCTION private.prevent_schedule_baseline_mutation();

REVOKE ALL ON FUNCTION private.prevent_schedule_baseline_mutation()
  FROM PUBLIC, anon, authenticated, service_role;

ALTER TABLE public.project_schedule_baselines ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "project_schedule_baselines_select"
  ON public.project_schedule_baselines;
CREATE POLICY "project_schedule_baselines_select"
  ON public.project_schedule_baselines
  FOR SELECT TO authenticated
  USING (public.can_access_schedule_submissions(project_id));

REVOKE ALL ON TABLE public.project_schedule_baselines
  FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON TABLE public.project_schedule_baselines TO authenticated;
REVOKE ALL ON SEQUENCE public.project_schedule_baselines_id_seq
  FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.approve_schedule_submission(
  p_submission_id bigint,
  p_comment text,
  p_client_request_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_role text;
  v_version public.project_schedule_versions%ROWTYPE;
  v_request public.write_command_requests%ROWTYPE;
  v_next_revision integer;
  v_task_count integer;
  v_activity_count integer := 0;
  v_scope_work_group_count integer := 0;
  v_snapshot_work_group_count integer := 0;
  v_baseline_id bigint;
  v_result jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF p_client_request_id IS NULL THEN
    RAISE EXCEPTION 'client_request_id is required' USING ERRCODE = '22023';
  END IF;

  SELECT lower(role) INTO v_role FROM public.profiles WHERE id = v_uid;

  SELECT * INTO v_version
  FROM public.project_schedule_versions
  WHERE id = p_submission_id
  FOR UPDATE;

  IF NOT FOUND
    OR v_role IS DISTINCT FROM 'pm'
    OR NOT public.can_write_project(v_version.project_id) THEN
    RAISE EXCEPTION 'Not authorized for this project schedule' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.write_command_requests(
    actor_id, operation, client_request_id, project_id, source_record_id
  ) VALUES (
    v_uid, 'schedule.approve', p_client_request_id,
    v_version.project_id, p_submission_id
  )
  ON CONFLICT (actor_id, operation, client_request_id) DO NOTHING;

  SELECT * INTO v_request
  FROM public.write_command_requests
  WHERE actor_id = v_uid
    AND operation = 'schedule.approve'
    AND client_request_id = p_client_request_id;

  IF v_request.source_record_id IS DISTINCT FROM p_submission_id THEN
    RAISE EXCEPTION 'Idempotency key belongs to another submission' USING ERRCODE = '23505';
  END IF;
  IF v_request.response IS NOT NULL THEN
    RETURN v_request.response || jsonb_build_object('idempotentReplay', true);
  END IF;

  IF v_version.status <> 'PENDING_REVIEW' THEN
    RAISE EXCEPTION 'SUBMISSION_NOT_PENDING: this submission is not awaiting review'
      USING ERRCODE = '55000';
  END IF;

  SELECT count(*) INTO v_task_count
  FROM public.project_schedule_version_tasks task
  WHERE task.version_id = p_submission_id;

  IF v_task_count = 0 THEN
    RAISE EXCEPTION 'BASELINE_SNAPSHOT_INCOMPLETE: submission has no immutable schedule rows'
      USING ERRCODE = '55000';
  END IF;

  IF v_version.execution_scope_version_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.project_execution_scope_versions scope
      WHERE scope.id = v_version.execution_scope_version_id
        AND scope.project_id = v_version.project_id
    ) THEN
      RAISE EXCEPTION 'BASELINE_SCOPE_INVALID: pinned Execution Scope does not belong to this project'
        USING ERRCODE = '55000';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.project_schedule_version_tasks task
      WHERE task.version_id = p_submission_id
        AND (
          task.schedule_activity_id IS NULL
          OR NULLIF(btrim(task.activity_title), '') IS NULL
          OR NULLIF(btrim(task.activity_phase_id), '') IS NULL
          OR NULLIF(btrim(task.activity_phase_label), '') IS NULL
        )
    ) THEN
      RAISE EXCEPTION 'BASELINE_ACTIVITY_SNAPSHOT_INCOMPLETE: canonical Activities require frozen identity, title and phase'
        USING ERRCODE = '55000';
    END IF;

    SELECT count(DISTINCT task.schedule_activity_id) INTO v_activity_count
    FROM public.project_schedule_version_tasks task
    WHERE task.version_id = p_submission_id;

    IF v_activity_count IS DISTINCT FROM v_task_count THEN
      RAISE EXCEPTION 'BASELINE_ACTIVITY_SNAPSHOT_INVALID: every schedule row requires one unique Activity UUID'
        USING ERRCODE = '55000';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.project_schedule_version_tasks task
      WHERE task.version_id = p_submission_id
        AND NOT EXISTS (
          SELECT 1
          FROM public.project_schedule_version_activity_work_groups mapping
          WHERE mapping.version_id = task.version_id
            AND mapping.schedule_activity_id = task.schedule_activity_id
        )
    ) THEN
      RAISE EXCEPTION 'BASELINE_WORK_GROUP_SNAPSHOT_INCOMPLETE: every Activity requires at least one Work Group'
        USING ERRCODE = '55000';
    END IF;

    SELECT count(*) INTO v_scope_work_group_count
    FROM public.project_execution_scope_items item
    WHERE item.execution_scope_version_id = v_version.execution_scope_version_id;

    SELECT count(DISTINCT mapping.work_group_id) INTO v_snapshot_work_group_count
    FROM public.project_schedule_version_activity_work_groups mapping
    WHERE mapping.version_id = p_submission_id
      AND mapping.execution_scope_version_id = v_version.execution_scope_version_id;

    IF v_scope_work_group_count = 0
      OR v_snapshot_work_group_count IS DISTINCT FROM v_scope_work_group_count THEN
      RAISE EXCEPTION 'BASELINE_SCOPE_COVERAGE_INCOMPLETE: submitted Activities must cover the pinned Execution Scope'
        USING ERRCODE = '55000';
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.project_schedule_baselines baseline
    WHERE baseline.project_id = v_version.project_id
  ) THEN
    RAISE EXCEPTION 'BASELINE_ALREADY_APPROVED: an official baseline already exists for this project'
      USING ERRCODE = '55000';
  END IF;

  SELECT COALESCE(max(baseline_revision_number), 0) + 1 INTO v_next_revision
  FROM public.project_schedule_baselines
  WHERE project_id = v_version.project_id;

  UPDATE public.project_schedule_versions
  SET status = 'APPROVED',
      reviewed_by = v_uid,
      reviewed_at = now(),
      pm_comment = NULLIF(p_comment, ''),
      baseline_revision_number = v_next_revision
  WHERE id = p_submission_id;

  INSERT INTO public.project_schedule_baselines (
    project_id, schedule_version_id, baseline_revision_number,
    execution_scope_version_id, approved_by, approved_at, pm_comment
  )
  SELECT
    version.project_id,
    version.id,
    version.baseline_revision_number,
    version.execution_scope_version_id,
    version.reviewed_by,
    version.reviewed_at,
    version.pm_comment
  FROM public.project_schedule_versions version
  WHERE version.id = p_submission_id
  RETURNING id INTO v_baseline_id;

  v_result := jsonb_build_object(
    'baselineId', v_baseline_id,
    'submissionId', p_submission_id,
    'projectId', v_version.project_id,
    'status', 'APPROVED',
    'baselineRevisionNumber', v_next_revision,
    'executionScopeVersionId', v_version.execution_scope_version_id,
    'activityCount', CASE WHEN v_version.execution_scope_version_id IS NULL THEN NULL ELSE v_activity_count END,
    'workGroupCount', CASE WHEN v_version.execution_scope_version_id IS NULL THEN NULL ELSE v_snapshot_work_group_count END
  );

  UPDATE public.write_command_requests
  SET response = v_result, completed_at = now()
  WHERE id = v_request.id;

  RETURN v_result || jsonb_build_object('idempotentReplay', false);
END;
$$;

REVOKE ALL ON FUNCTION public.approve_schedule_submission(bigint, text, uuid)
  FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.approve_schedule_submission(bigint, text, uuid)
  TO authenticated;

-- MIGRATION 067_project_boq_foundation.sql SHA256 37b0c97906063fd1e62da339b09050f99aba5b11dd2f4905c68b23bf9949784c
-- 067_project_boq_foundation.sql
-- Roadmap Phase C.11: native, versioned BOQ domain/data foundation.
-- Deliberately excludes Work Group aggregation, BOQ -> Execution Scope
-- mapping, Excel I/O, tender rounds, bidder access, and the native editor.

CREATE UNIQUE INDEX IF NOT EXISTS work_ontology_boq_definitions_version_id_group_uniq
  ON public.work_ontology_boq_item_definitions(ontology_version_id, id, work_group_id);

CREATE TABLE IF NOT EXISTS public.project_boqs (
  id uuid PRIMARY KEY,
  project_id bigint NOT NULL REFERENCES public.projects(id) ON DELETE RESTRICT,
  ontology_version_id uuid NOT NULL REFERENCES public.work_ontology_versions(id) ON DELETE RESTRICT,
  title text NOT NULL CHECK (btrim(title) <> ''),
  currency_code text NOT NULL CHECK (currency_code ~ '^[A-Z]{3}$'),
  created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (id, project_id, ontology_version_id)
);

CREATE INDEX IF NOT EXISTS project_boqs_project_idx ON public.project_boqs(project_id);

CREATE TABLE IF NOT EXISTS public.project_boq_versions (
  id bigserial PRIMARY KEY,
  boq_id uuid NOT NULL,
  project_id bigint NOT NULL,
  ontology_version_id uuid NOT NULL,
  revision_number integer NOT NULL CHECK (revision_number > 0),
  source_kind text NOT NULL DEFAULT 'NATIVE' CHECK (source_kind IN ('NATIVE', 'IMPORT', 'SYSTEM')),
  revision_note text,
  created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (boq_id, revision_number),
  UNIQUE (id, boq_id, project_id, ontology_version_id),
  FOREIGN KEY (boq_id, project_id, ontology_version_id)
    REFERENCES public.project_boqs(id, project_id, ontology_version_id)
    ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS project_boq_versions_project_idx
  ON public.project_boq_versions(project_id, created_at DESC);

CREATE TABLE IF NOT EXISTS public.project_boq_items (
  boq_version_id bigint NOT NULL,
  line_id uuid NOT NULL,
  boq_id uuid NOT NULL,
  project_id bigint NOT NULL,
  ontology_version_id uuid NOT NULL,
  work_group_id uuid NOT NULL,
  item_kind text NOT NULL CHECK (item_kind IN ('STANDARD', 'CUSTOM')),
  standard_definition_id uuid,
  description text NOT NULL CHECK (btrim(description) <> ''),
  unit text NOT NULL CHECK (btrim(unit) <> ''),
  quantity numeric(20,6) NOT NULL CHECK (quantity > 0),
  unit_rate numeric(20,6) CHECK (unit_rate IS NULL OR unit_rate >= 0),
  line_total numeric(24,2) GENERATED ALWAYS AS (round(quantity * unit_rate, 2)) STORED,
  contractor_note text,
  reference text,
  specification text,
  sort_order integer NOT NULL CHECK (sort_order >= 0),
  PRIMARY KEY (boq_version_id, line_id),
  FOREIGN KEY (boq_version_id, boq_id, project_id, ontology_version_id)
    REFERENCES public.project_boq_versions(id, boq_id, project_id, ontology_version_id)
    ON DELETE RESTRICT,
  FOREIGN KEY (ontology_version_id, work_group_id)
    REFERENCES public.work_ontology_work_groups(ontology_version_id, id)
    ON DELETE RESTRICT,
  FOREIGN KEY (ontology_version_id, standard_definition_id, work_group_id)
    REFERENCES public.work_ontology_boq_item_definitions(ontology_version_id, id, work_group_id)
    ON DELETE RESTRICT,
  CONSTRAINT project_boq_items_kind_shape_check CHECK (
    (item_kind = 'STANDARD' AND standard_definition_id IS NOT NULL)
    OR (item_kind = 'CUSTOM' AND standard_definition_id IS NULL)
  )
);

CREATE INDEX IF NOT EXISTS project_boq_items_version_sort_idx
  ON public.project_boq_items(boq_version_id, sort_order, line_id);
CREATE INDEX IF NOT EXISTS project_boq_items_work_group_idx
  ON public.project_boq_items(ontology_version_id, work_group_id);

CREATE OR REPLACE FUNCTION private.prevent_project_boq_snapshot_mutation()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog
AS $$
BEGIN
  RAISE EXCEPTION 'PROJECT_BOQ_SNAPSHOT_IMMUTABLE' USING ERRCODE = '55000';
END;
$$;

