  TO authenticated;
REVOKE ALL ON SEQUENCE public.project_boq_versions_id_seq
  FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.save_project_boq_revision(
  p_project_id bigint,
  p_boq_id uuid,
  p_title text,
  p_currency_code text,
  p_items jsonb,
  p_expected_latest_revision integer,
  p_revision_note text,
  p_client_request_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_role text;
  v_project_ontology_version_id uuid;
  v_existing_boq public.project_boqs%ROWTYPE;
  v_request public.write_command_requests%ROWTYPE;
  v_current_revision integer;
  v_next_revision integer;
  v_version_id bigint;
  v_line_count integer;
  v_priced_line_count integer;
  v_total numeric(24,2);
  v_result jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF p_boq_id IS NULL OR p_client_request_id IS NULL THEN
    RAISE EXCEPTION 'boq_id and client_request_id are required' USING ERRCODE = '22023';
  END IF;
  IF NULLIF(btrim(COALESCE(p_title, '')), '') IS NULL THEN
    RAISE EXCEPTION 'BOQ_TITLE_REQUIRED: title is required' USING ERRCODE = '22023';
  END IF;
  IF COALESCE(p_currency_code, '') !~ '^[A-Z]{3}$' THEN
    RAISE EXCEPTION 'INVALID_CURRENCY_CODE: use an ISO-style three-letter uppercase code'
      USING ERRCODE = '22023';
  END IF;
  IF p_expected_latest_revision IS NULL OR p_expected_latest_revision < 0 THEN
    RAISE EXCEPTION 'INVALID_EXPECTED_REVISION: expected revision must be zero or greater'
      USING ERRCODE = '22023';
  END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'EMPTY_BOQ: at least one BOQ line is required' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.write_command_requests(actor_id, operation, client_request_id, project_id)
  VALUES (v_uid, 'boq.save_revision', p_client_request_id, p_project_id)
  ON CONFLICT (actor_id, operation, client_request_id) DO NOTHING;

  SELECT * INTO v_request
  FROM public.write_command_requests
  WHERE actor_id = v_uid
    AND operation = 'boq.save_revision'
    AND client_request_id = p_client_request_id;

  IF v_request.project_id <> p_project_id THEN
    RAISE EXCEPTION 'Idempotency key belongs to another project' USING ERRCODE = '23505';
  END IF;
  IF v_request.response IS NOT NULL THEN
    IF v_request.response->>'boqId' IS DISTINCT FROM p_boq_id::text THEN
      RAISE EXCEPTION 'Idempotency key belongs to another BOQ' USING ERRCODE = '23505';
    END IF;
    RETURN v_request.response || jsonb_build_object('idempotentReplay', true);
  END IF;

  SELECT project.work_ontology_version_id
    INTO v_project_ontology_version_id
  FROM public.projects project
  WHERE project.id = p_project_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Project % not found', p_project_id USING ERRCODE = 'P0002';
  END IF;
  IF v_project_ontology_version_id IS NULL THEN
    RAISE EXCEPTION 'PROJECT_BOQ_REQUIRES_WORK_ONTOLOGY: project is not pinned to a Work Ontology'
      USING ERRCODE = '55000';
  END IF;

  SELECT lower(role) INTO v_role FROM public.profiles WHERE id = v_uid;
  IF v_role IS NULL
     OR v_role NOT IN ('pm', 'admin')
     OR public.can_write_project(p_project_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'Not authorized to manage this project BOQ' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_existing_boq
  FROM public.project_boqs boq
  WHERE boq.id = p_boq_id
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing_boq.project_id IS DISTINCT FROM p_project_id
      OR v_existing_boq.ontology_version_id IS DISTINCT FROM v_project_ontology_version_id THEN
      RAISE EXCEPTION 'BOQ_IDENTITY_CONFLICT: BOQ belongs to another project or ontology'
        USING ERRCODE = '23505';
    END IF;
    IF v_existing_boq.title IS DISTINCT FROM btrim(p_title)
      OR v_existing_boq.currency_code IS DISTINCT FROM p_currency_code THEN
      RAISE EXCEPTION 'BOQ_METADATA_IMMUTABLE: title and currency are pinned when the BOQ is created'
        USING ERRCODE = '55000';
    END IF;
  ELSE
    IF p_expected_latest_revision <> 0 THEN
      RAISE EXCEPTION 'BOQ_REVISION_CONFLICT: expected existing revision %, but BOQ does not exist',
        p_expected_latest_revision USING ERRCODE = '40001';
    END IF;
    INSERT INTO public.project_boqs(
      id, project_id, ontology_version_id, title, currency_code, created_by
    ) VALUES (
      p_boq_id, p_project_id, v_project_ontology_version_id,
      btrim(p_title), p_currency_code, v_uid
    );
  END IF;

  SELECT COALESCE(max(version.revision_number), 0)
    INTO v_current_revision
  FROM public.project_boq_versions version
  WHERE version.boq_id = p_boq_id;

  IF v_current_revision IS DISTINCT FROM p_expected_latest_revision THEN
    RAISE EXCEPTION 'BOQ_REVISION_CONFLICT: expected revision %, current revision %',
      p_expected_latest_revision, v_current_revision USING ERRCODE = '40001';
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_items) item
    WHERE jsonb_typeof(item) <> 'object'
      OR COALESCE(item->>'lineId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      OR COALESCE(item->>'workGroupId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      OR COALESCE(item->>'itemKind', '') NOT IN ('STANDARD', 'CUSTOM')
      OR btrim(COALESCE(item->>'description', '')) = ''
      OR btrim(COALESCE(item->>'unit', '')) = ''
      OR COALESCE(item->>'quantity', '') !~ '^[0-9]+(?:\.[0-9]+)?$'
      OR (item->>'quantity')::numeric <= 0
      OR (
        item->>'unitRate' IS NOT NULL
        AND (
          item->>'unitRate' !~ '^[0-9]+(?:\.[0-9]+)?$'
          OR (item->>'unitRate')::numeric < 0
        )
      )
      OR COALESCE(item->>'sortOrder', '') !~ '^[0-9]+$'
      OR (
        item->>'itemKind' = 'STANDARD'
        AND COALESCE(item->>'standardDefinitionId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      )
      OR (item->>'itemKind' = 'CUSTOM' AND item->>'standardDefinitionId' IS NOT NULL)
  ) THEN
    RAISE EXCEPTION 'INVALID_BOQ_LINE: every line requires valid identity, Work Group, kind, description, unit, quantity and order'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_items) item
    GROUP BY item->>'lineId' HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'DUPLICATE_BOQ_LINE: line IDs must be unique within a revision'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_items) item
    LEFT JOIN public.work_ontology_work_groups work_group
      ON work_group.ontology_version_id = v_project_ontology_version_id
     AND work_group.id = (item->>'workGroupId')::uuid
    WHERE work_group.id IS NULL
  ) THEN
    RAISE EXCEPTION 'UNKNOWN_BOQ_WORK_GROUP: every line must reference the pinned Work Ontology'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_items) item
    LEFT JOIN public.work_ontology_boq_item_definitions definition
      ON definition.ontology_version_id = v_project_ontology_version_id
     AND definition.id = (item->>'standardDefinitionId')::uuid
     AND definition.work_group_id = (item->>'workGroupId')::uuid
    WHERE item->>'itemKind' = 'STANDARD' AND definition.id IS NULL
  ) THEN
    RAISE EXCEPTION 'INVALID_STANDARD_BOQ_DEFINITION: standard line definition must belong to its Work Group'
      USING ERRCODE = '22023';
  END IF;

  v_next_revision := v_current_revision + 1;
  INSERT INTO public.project_boq_versions(
    boq_id, project_id, ontology_version_id, revision_number,
    source_kind, revision_note, created_by
  ) VALUES (
    p_boq_id, p_project_id, v_project_ontology_version_id, v_next_revision,
    'NATIVE', NULLIF(btrim(COALESCE(p_revision_note, '')), ''), v_uid
  ) RETURNING id INTO v_version_id;

  INSERT INTO public.project_boq_items(
    boq_version_id, line_id, boq_id, project_id, ontology_version_id,
    work_group_id, item_kind, standard_definition_id, description, unit,
    quantity, unit_rate, contractor_note, reference, specification, sort_order
  )
  SELECT
    v_version_id,
    (item->>'lineId')::uuid,
    p_boq_id,
    p_project_id,
    v_project_ontology_version_id,
    (item->>'workGroupId')::uuid,
    item->>'itemKind',
    NULLIF(item->>'standardDefinitionId', '')::uuid,
    btrim(item->>'description'),
    btrim(item->>'unit'),
    (item->>'quantity')::numeric,
    NULLIF(item->>'unitRate', '')::numeric,
    NULLIF(btrim(COALESCE(item->>'contractorNote', '')), ''),
    NULLIF(btrim(COALESCE(item->>'reference', '')), ''),
    NULLIF(btrim(COALESCE(item->>'specification', '')), ''),
    (item->>'sortOrder')::integer
  FROM jsonb_array_elements(p_items) item;

  SELECT count(*), count(*) FILTER (WHERE item.unit_rate IS NOT NULL), COALESCE(sum(item.line_total), 0)
    INTO v_line_count, v_priced_line_count, v_total
  FROM public.project_boq_items item
  WHERE item.boq_version_id = v_version_id;

  v_result := jsonb_build_object(
    'boqId', p_boq_id,
    'projectId', p_project_id,
    'ontologyVersionId', v_project_ontology_version_id,
    'versionId', v_version_id,
    'revisionNumber', v_next_revision,
    'lineCount', v_line_count,
    'pricedLineCount', v_priced_line_count,
    'total', v_total,
    'currencyCode', p_currency_code
  );

  UPDATE public.write_command_requests
  SET response = v_result, completed_at = now()
  WHERE id = v_request.id;

  RETURN v_result || jsonb_build_object('idempotentReplay', false);
END;
$$;

REVOKE ALL ON FUNCTION public.save_project_boq_revision(
  bigint, uuid, text, text, jsonb, integer, text, uuid
) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.save_project_boq_revision(
  bigint, uuid, text, text, jsonb, integer, text, uuid
) TO authenticated;

-- MIGRATION 068_project_boq_work_group_aggregation.sql SHA256 8ec6721ed6a1aa1f6e52dbdfa0398d124246f77d2ea1fac1851c2da77a1a0e00
-- 068_project_boq_work_group_aggregation.sql
-- Roadmap Phase C.12: deterministic Work Group commercial rollups for one
-- immutable Project BOQ revision. No snapshot data is copied or mutated.

CREATE OR REPLACE VIEW public.project_boq_work_group_totals
WITH (security_invoker = true)
AS
SELECT
  item.boq_version_id,
  item.boq_id,
  item.project_id,
  item.ontology_version_id,
  boq.currency_code,
  version.revision_number,
  discipline.id AS discipline_id,
  discipline.code AS discipline_code,
  discipline.label AS discipline_label,
  discipline.display_order AS discipline_display_order,
  work_group.id AS work_group_id,
  work_group.code AS work_group_code,
  work_group.label AS work_group_label,
  work_group.display_order AS work_group_display_order,
  count(*)::integer AS line_count,
  count(*) FILTER (WHERE item.item_kind = 'STANDARD')::integer AS standard_line_count,
  count(*) FILTER (WHERE item.item_kind = 'CUSTOM')::integer AS custom_line_count,
  count(*) FILTER (WHERE item.unit_rate IS NOT NULL)::integer AS priced_line_count,
  count(*) FILTER (WHERE item.unit_rate IS NULL)::integer AS unpriced_line_count,
  COALESCE(sum(item.line_total), 0)::numeric(24,2) AS priced_total,
  bool_and(item.unit_rate IS NOT NULL) AS is_fully_priced
FROM public.project_boq_items item
JOIN public.project_boq_versions version
  ON version.id = item.boq_version_id
 AND version.boq_id = item.boq_id
 AND version.project_id = item.project_id
 AND version.ontology_version_id = item.ontology_version_id
JOIN public.project_boqs boq
  ON boq.id = item.boq_id
 AND boq.project_id = item.project_id
 AND boq.ontology_version_id = item.ontology_version_id
JOIN public.work_ontology_work_groups work_group
  ON work_group.ontology_version_id = item.ontology_version_id
 AND work_group.id = item.work_group_id
JOIN public.work_ontology_disciplines discipline
  ON discipline.ontology_version_id = work_group.ontology_version_id
 AND discipline.id = work_group.discipline_id
GROUP BY
  item.boq_version_id,
  item.boq_id,
  item.project_id,
  item.ontology_version_id,
  boq.currency_code,
  version.revision_number,
  discipline.id,
  discipline.code,
  discipline.label,
  discipline.display_order,
  work_group.id,
  work_group.code,
  work_group.label,
  work_group.display_order;

COMMENT ON VIEW public.project_boq_work_group_totals IS
  'C.12 read-only Work Group totals projected from immutable Project BOQ revisions.';

REVOKE ALL ON TABLE public.project_boq_work_group_totals
  FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON TABLE public.project_boq_work_group_totals TO authenticated;

-- MIGRATION 069_project_boq_standard_custom_items.sql SHA256 6e28339687c116aa04f0d8c3d44f5de9bdfa8eef5c99a70eeb3ece48f10c053c
-- 069_project_boq_standard_custom_items.sql
-- Roadmap Phase C.13: stable STANDARD/CUSTOM BOQ item lifecycle.
-- Native editor ownership and bidder access remain Phase D concerns.

CREATE TABLE IF NOT EXISTS public.project_boq_item_identities (
  boq_id uuid NOT NULL,
  line_id uuid NOT NULL,
  project_id bigint NOT NULL,
  ontology_version_id uuid NOT NULL,
  work_group_id uuid NOT NULL,
  item_kind text NOT NULL CHECK (item_kind IN ('STANDARD', 'CUSTOM')),
  standard_definition_id uuid,
  first_seen_version_id bigint NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (boq_id, line_id),
  FOREIGN KEY (boq_id, project_id, ontology_version_id)
    REFERENCES public.project_boqs(id, project_id, ontology_version_id)
    ON DELETE RESTRICT,
  FOREIGN KEY (first_seen_version_id, boq_id, project_id, ontology_version_id)
    REFERENCES public.project_boq_versions(id, boq_id, project_id, ontology_version_id)
    ON DELETE RESTRICT,
  FOREIGN KEY (ontology_version_id, work_group_id)
    REFERENCES public.work_ontology_work_groups(ontology_version_id, id)
    ON DELETE RESTRICT,
  FOREIGN KEY (ontology_version_id, standard_definition_id, work_group_id)
    REFERENCES public.work_ontology_boq_item_definitions(ontology_version_id, id, work_group_id)
    ON DELETE RESTRICT,
  CONSTRAINT project_boq_item_identities_kind_shape_check CHECK (
    (item_kind = 'STANDARD' AND standard_definition_id IS NOT NULL)
    OR (item_kind = 'CUSTOM' AND standard_definition_id IS NULL)
  )
);

CREATE INDEX IF NOT EXISTS project_boq_item_identities_project_idx
  ON public.project_boq_item_identities(project_id, boq_id);

INSERT INTO public.project_boq_item_identities(
  boq_id, line_id, project_id, ontology_version_id, work_group_id,
  item_kind, standard_definition_id, first_seen_version_id
)
SELECT DISTINCT ON (item.boq_id, item.line_id)
  item.boq_id,
  item.line_id,
  item.project_id,
  item.ontology_version_id,
  item.work_group_id,
  item.item_kind,
  item.standard_definition_id,
  item.boq_version_id
FROM public.project_boq_items item
JOIN public.project_boq_versions version ON version.id = item.boq_version_id
ORDER BY item.boq_id, item.line_id, version.revision_number, item.boq_version_id
ON CONFLICT (boq_id, line_id) DO NOTHING;

DO $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.project_boq_items item
    JOIN public.project_boq_item_identities identity
      ON identity.boq_id = item.boq_id AND identity.line_id = item.line_id
    WHERE identity.project_id IS DISTINCT FROM item.project_id
       OR identity.ontology_version_id IS DISTINCT FROM item.ontology_version_id
       OR identity.work_group_id IS DISTINCT FROM item.work_group_id
       OR identity.item_kind IS DISTINCT FROM item.item_kind
       OR identity.standard_definition_id IS DISTINCT FROM item.standard_definition_id
  ) THEN
    RAISE EXCEPTION 'PROJECT_BOQ_LINE_IDENTITY_HISTORY_CONFLICT'
      USING ERRCODE = '23514';
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION private.enforce_project_boq_item_identity()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_catalog
AS $$
DECLARE
  existing_identity public.project_boq_item_identities%ROWTYPE;
  standard_definition public.work_ontology_boq_item_definitions%ROWTYPE;
BEGIN
  SELECT * INTO existing_identity
  FROM public.project_boq_item_identities identity
  WHERE identity.boq_id = NEW.boq_id AND identity.line_id = NEW.line_id;

  IF FOUND THEN
    IF existing_identity.project_id IS DISTINCT FROM NEW.project_id
       OR existing_identity.ontology_version_id IS DISTINCT FROM NEW.ontology_version_id
       OR existing_identity.work_group_id IS DISTINCT FROM NEW.work_group_id
       OR existing_identity.item_kind IS DISTINCT FROM NEW.item_kind
       OR existing_identity.standard_definition_id IS DISTINCT FROM NEW.standard_definition_id THEN
      RAISE EXCEPTION 'PROJECT_BOQ_LINE_IDENTITY_IMMUTABLE: line % cannot change kind or classification', NEW.line_id
        USING ERRCODE = '23514';
    END IF;
  ELSE
    INSERT INTO public.project_boq_item_identities(
      boq_id, line_id, project_id, ontology_version_id, work_group_id,
      item_kind, standard_definition_id, first_seen_version_id
    ) VALUES (
      NEW.boq_id, NEW.line_id, NEW.project_id, NEW.ontology_version_id, NEW.work_group_id,
      NEW.item_kind, NEW.standard_definition_id, NEW.boq_version_id
    );
  END IF;

  IF NEW.item_kind = 'STANDARD' THEN
    SELECT * INTO standard_definition
    FROM public.work_ontology_boq_item_definitions definition
    WHERE definition.ontology_version_id = NEW.ontology_version_id
      AND definition.id = NEW.standard_definition_id
      AND definition.work_group_id = NEW.work_group_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'INVALID_STANDARD_BOQ_DEFINITION'
        USING ERRCODE = '23503';
    END IF;
    IF btrim(NEW.description) IS DISTINCT FROM standard_definition.label
       OR btrim(NEW.unit) IS DISTINCT FROM standard_definition.default_unit THEN
      RAISE EXCEPTION 'STANDARD_BOQ_METADATA_MISMATCH: standard description and unit are ontology-controlled'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS project_boq_items_enforce_identity ON public.project_boq_items;
CREATE TRIGGER project_boq_items_enforce_identity
  BEFORE INSERT ON public.project_boq_items
  FOR EACH ROW EXECUTE FUNCTION private.enforce_project_boq_item_identity();

DROP TRIGGER IF EXISTS project_boq_item_identities_immutable ON public.project_boq_item_identities;
CREATE TRIGGER project_boq_item_identities_immutable
  BEFORE UPDATE OR DELETE ON public.project_boq_item_identities
  FOR EACH ROW EXECUTE FUNCTION private.prevent_project_boq_snapshot_mutation();

REVOKE ALL ON FUNCTION private.enforce_project_boq_item_identity()
  FROM PUBLIC, anon, authenticated, service_role;

ALTER TABLE public.project_boq_item_identities ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "project_boq_item_identities_select" ON public.project_boq_item_identities;
CREATE POLICY "project_boq_item_identities_select" ON public.project_boq_item_identities
  FOR SELECT TO authenticated USING (public.can_access_project(project_id));

REVOKE ALL ON TABLE public.project_boq_item_identities
  FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON TABLE public.project_boq_item_identities TO authenticated;

-- MIGRATION 070_project_boq_execution_scope_mapping.sql SHA256 19c96e579bed3991e12e1b0be3f9c17979ea80725984305552f3c0ad3b93b6da
-- 070_project_boq_execution_scope_mapping.sql
-- Roadmap Phase C.14: deterministic BOQ revision -> Execution Scope mapping.
-- Detailed BOQ lines collapse to distinct canonical Work Groups; no Gantt
-- activities, dates, durations, dependencies or tender-award state are made.

ALTER TABLE public.project_execution_scope_versions
  DROP CONSTRAINT IF EXISTS project_execution_scope_versions_source_kind_check;
ALTER TABLE public.project_execution_scope_versions
  ADD COLUMN IF NOT EXISTS source_boq_version_id bigint;
ALTER TABLE public.project_execution_scope_versions
  ADD CONSTRAINT project_execution_scope_versions_source_kind_check
  CHECK (source_kind IN ('PM_DISCIPLINE_SCOPE', 'BOQ_REVISION'));
ALTER TABLE public.project_execution_scope_versions
  ADD CONSTRAINT project_execution_scope_versions_source_boq_version_fk
  FOREIGN KEY (source_boq_version_id)
  REFERENCES public.project_boq_versions(id) ON DELETE RESTRICT;
ALTER TABLE public.project_execution_scope_versions
  ADD CONSTRAINT project_execution_scope_versions_source_shape_check
  CHECK (
    (source_kind = 'PM_DISCIPLINE_SCOPE' AND source_boq_version_id IS NULL)
    OR (source_kind = 'BOQ_REVISION' AND source_boq_version_id IS NOT NULL)
  );

CREATE UNIQUE INDEX IF NOT EXISTS project_execution_scope_versions_boq_source_uniq
  ON public.project_execution_scope_versions(project_id, source_boq_version_id)
  WHERE source_boq_version_id IS NOT NULL;

CREATE OR REPLACE FUNCTION public.materialize_project_execution_scope_from_boq(
  p_project_id bigint,
  p_boq_version_id bigint,
  p_expected_latest_scope_revision integer,
  p_client_request_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, private, pg_temp
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_role text;
  v_project public.projects%ROWTYPE;
  v_boq_version public.project_boq_versions%ROWTYPE;
  v_request public.write_command_requests%ROWTYPE;
  v_existing_scope public.project_execution_scope_versions%ROWTYPE;
  v_current_revision integer;
  v_next_revision integer;
  v_scope_version_id bigint;
  v_project_discipline_ids uuid[];
  v_selected_discipline_ids uuid[];
  v_boq_line_count integer;
  v_work_group_count integer;
  v_result jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF p_boq_version_id IS NULL OR p_client_request_id IS NULL THEN
    RAISE EXCEPTION 'boq_version_id and client_request_id are required' USING ERRCODE = '22023';
  END IF;
  IF p_expected_latest_scope_revision IS NULL OR p_expected_latest_scope_revision < 0 THEN
    RAISE EXCEPTION 'INVALID_EXPECTED_SCOPE_REVISION' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.write_command_requests(actor_id, operation, client_request_id, project_id)
  VALUES (v_uid, 'boq.materialize_execution_scope', p_client_request_id, p_project_id)
  ON CONFLICT (actor_id, operation, client_request_id) DO NOTHING;

  SELECT * INTO v_request
  FROM public.write_command_requests request
  WHERE request.actor_id = v_uid
    AND request.operation = 'boq.materialize_execution_scope'
    AND request.client_request_id = p_client_request_id;

  IF v_request.project_id IS DISTINCT FROM p_project_id THEN
    RAISE EXCEPTION 'Idempotency key belongs to another project' USING ERRCODE = '23505';
  END IF;
  IF v_request.response IS NOT NULL THEN
    IF (v_request.response->>'sourceBoqVersionId')::bigint IS DISTINCT FROM p_boq_version_id THEN
      RAISE EXCEPTION 'Idempotency key belongs to another BOQ version' USING ERRCODE = '23505';
    END IF;
    RETURN v_request.response || jsonb_build_object('idempotentReplay', true);
  END IF;

  SELECT * INTO v_project
  FROM public.projects project
  WHERE project.id = p_project_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Project % not found', p_project_id USING ERRCODE = 'P0002';
  END IF;
  IF v_project.work_ontology_version_id IS NULL THEN
    RAISE EXCEPTION 'PROJECT_EXECUTION_SCOPE_REQUIRES_WORK_ONTOLOGY' USING ERRCODE = '55000';
  END IF;

  SELECT lower(profile.role) INTO v_role
  FROM public.profiles profile WHERE profile.id = v_uid;
  IF v_role IS NULL OR v_role NOT IN ('pm', 'admin')
     OR public.can_write_project(p_project_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'Not authorized to materialize Execution Scope' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_boq_version
  FROM public.project_boq_versions version
  WHERE version.id = p_boq_version_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'BOQ version % not found', p_boq_version_id USING ERRCODE = 'P0002';
  END IF;
  IF v_boq_version.project_id IS DISTINCT FROM p_project_id
     OR v_boq_version.ontology_version_id IS DISTINCT FROM v_project.work_ontology_version_id THEN
    RAISE EXCEPTION 'BOQ_EXECUTION_SCOPE_SOURCE_MISMATCH' USING ERRCODE = '23514';
  END IF;

  SELECT array_agg(value::uuid ORDER BY value::uuid)
    INTO v_project_discipline_ids
  FROM jsonb_array_elements_text(v_project.scope->'disciplineIds') value;

  IF EXISTS (
    SELECT 1
    FROM public.project_boq_items item
    JOIN public.work_ontology_work_groups work_group
      ON work_group.ontology_version_id = item.ontology_version_id
     AND work_group.id = item.work_group_id
    WHERE item.boq_version_id = p_boq_version_id
      AND NOT (work_group.discipline_id = ANY(v_project_discipline_ids))
  ) THEN
    RAISE EXCEPTION 'BOQ_WORK_GROUP_OUTSIDE_PROJECT_DISCIPLINE_SCOPE' USING ERRCODE = '23514';
  END IF;

  SELECT count(*), count(DISTINCT item.work_group_id)
    INTO v_boq_line_count, v_work_group_count
  FROM public.project_boq_items item
  WHERE item.boq_version_id = p_boq_version_id;
  IF v_boq_line_count = 0 OR v_work_group_count = 0 THEN
    RAISE EXCEPTION 'EMPTY_BOQ_EXECUTION_SCOPE' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_existing_scope
  FROM public.project_execution_scope_versions scope
  WHERE scope.project_id = p_project_id
    AND scope.source_boq_version_id = p_boq_version_id;
  IF FOUND THEN
    v_result := jsonb_build_object(
      'projectId', p_project_id,
      'executionScopeVersionId', v_existing_scope.id,
      'revisionNumber', v_existing_scope.revision_number,
      'sourceKind', v_existing_scope.source_kind,
      'sourceBoqVersionId', p_boq_version_id,
      'boqLineCount', v_boq_line_count,
      'workGroupCount', v_work_group_count,
      'collapsedLineCount', v_boq_line_count - v_work_group_count,
      'alreadyMaterialized', true
    );
    UPDATE public.write_command_requests
    SET response = v_result, completed_at = now() WHERE id = v_request.id;
    RETURN v_result || jsonb_build_object('idempotentReplay', false);
  END IF;

  SELECT COALESCE(max(scope.revision_number), 0)
    INTO v_current_revision
  FROM public.project_execution_scope_versions scope
  WHERE scope.project_id = p_project_id;
  IF v_current_revision IS DISTINCT FROM p_expected_latest_scope_revision THEN
    RAISE EXCEPTION 'EXECUTION_SCOPE_REVISION_CONFLICT: expected %, current %',
      p_expected_latest_scope_revision, v_current_revision USING ERRCODE = '40001';
  END IF;

  SELECT array_agg(selected.discipline_id ORDER BY selected.discipline_display_order, selected.discipline_id)
    INTO v_selected_discipline_ids
  FROM (
    SELECT DISTINCT discipline.id AS discipline_id, discipline.display_order AS discipline_display_order
    FROM public.project_boq_items item
    JOIN public.work_ontology_work_groups work_group
      ON work_group.ontology_version_id = item.ontology_version_id
     AND work_group.id = item.work_group_id
    JOIN public.work_ontology_disciplines discipline
      ON discipline.ontology_version_id = work_group.ontology_version_id
     AND discipline.id = work_group.discipline_id
    WHERE item.boq_version_id = p_boq_version_id
  ) selected;

  v_next_revision := v_current_revision + 1;
  INSERT INTO public.project_execution_scope_versions(
    project_id, ontology_version_id, revision_number, source_kind,
    source_fingerprint, selected_discipline_ids, source_boq_version_id, created_by
  ) VALUES (
    p_project_id, v_boq_version.ontology_version_id, v_next_revision, 'BOQ_REVISION',
    'BOQ_REVISION:' || p_boq_version_id::text,
    v_selected_discipline_ids, p_boq_version_id, v_uid
  ) RETURNING id INTO v_scope_version_id;

  INSERT INTO public.project_execution_scope_items(
    execution_scope_version_id, ontology_version_id, discipline_id, work_group_id
  )
  SELECT DISTINCT
    v_scope_version_id, item.ontology_version_id, work_group.discipline_id, item.work_group_id
  FROM public.project_boq_items item
  JOIN public.work_ontology_work_groups work_group
    ON work_group.ontology_version_id = item.ontology_version_id
   AND work_group.id = item.work_group_id
  WHERE item.boq_version_id = p_boq_version_id
  ORDER BY work_group.discipline_id, item.work_group_id;

  v_result := jsonb_build_object(
    'projectId', p_project_id,
    'executionScopeVersionId', v_scope_version_id,
    'revisionNumber', v_next_revision,
    'sourceKind', 'BOQ_REVISION',
    'sourceBoqVersionId', p_boq_version_id,
    'boqLineCount', v_boq_line_count,
    'workGroupCount', v_work_group_count,
    'collapsedLineCount', v_boq_line_count - v_work_group_count,
    'alreadyMaterialized', false
  );
  UPDATE public.write_command_requests
  SET response = v_result, completed_at = now() WHERE id = v_request.id;
  RETURN v_result || jsonb_build_object('idempotentReplay', false);
END;
$$;

REVOKE ALL ON FUNCTION public.materialize_project_execution_scope_from_boq(
  bigint, bigint, integer, uuid
) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.materialize_project_execution_scope_from_boq(
  bigint, bigint, integer, uuid
) TO authenticated;

