CREATE OR REPLACE FUNCTION public.decide_payment_certification(p_certification_case_id uuid,p_decision_id uuid,p_decision_type text,p_certified_amount numeric,p_decision_reason text,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE u uuid:=auth.uid();v_role text;c public.project_payment_certification_cases%ROWTYPE;e public.project_payment_certification_evidence%ROWTYPE;m public.project_payment_milestones%ROWTYPE;s public.project_payment_schedules%ROWTYPE;req public.write_command_requests%ROWTYPE;kind text:=upper(btrim(COALESCE(p_decision_type,'')));amount numeric:=COALESCE(p_certified_amount,0);decision_no integer;next_status text;held numeric;result jsonb;
BEGIN SELECT upper(p.role)INTO v_role FROM public.profiles p WHERE p.id=u;SELECT *INTO c FROM public.project_payment_certification_cases WHERE id=p_certification_case_id FOR UPDATE;IF c.id IS NULL THEN RAISE EXCEPTION'PAYMENT_CERTIFICATION_CASE_NOT_FOUND'USING ERRCODE='P0002';END IF;SELECT *INTO e FROM public.project_payment_certification_evidence WHERE certification_case_id=c.id;SELECT *INTO m FROM public.project_payment_milestones WHERE id=c.milestone_id FOR UPDATE;SELECT *INTO s FROM public.project_payment_schedules WHERE id=m.payment_schedule_id;IF u IS NULL OR v_role NOT IN('PM','ADMIN')OR public.can_write_project(c.project_id)IS NOT TRUE THEN RAISE EXCEPTION'PAYMENT_CERTIFICATION_DECISION_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_decision_id IS NULL OR p_client_request_id IS NULL OR kind NOT IN('FULL','PARTIAL','HELD')OR btrim(COALESCE(p_decision_reason,''))=''OR char_length(p_decision_reason)>3000 OR c.status NOT IN('UNDER_CERTIFICATION','HELD')THEN RAISE EXCEPTION'INVALID_CERTIFICATION_DECISION_COMMAND'USING ERRCODE='22023';END IF;IF c.status='HELD'AND kind='HELD'THEN RAISE EXCEPTION'CERTIFICATION_ALREADY_HELD'USING ERRCODE='55000';END IF;IF kind='FULL'AND(e.evidence_ready IS NOT TRUE OR amount<>m.planned_amount)THEN RAISE EXCEPTION'FULL_CERTIFICATION_REQUIRES_READY_EVIDENCE_AND_FULL_AMOUNT'USING ERRCODE='22023';ELSIF kind='PARTIAL'AND(amount<=0 OR amount>=m.planned_amount)THEN RAISE EXCEPTION'PARTIAL_CERTIFICATION_AMOUNT_OUT_OF_RANGE'USING ERRCODE='22023';ELSIF kind='HELD'AND amount<>0 THEN RAISE EXCEPTION'HELD_CERTIFICATION_AMOUNT_MUST_BE_ZERO'USING ERRCODE='22023';END IF;INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'payment_certification.decide',p_client_request_id,c.project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT *INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='payment_certification.decide'AND client_request_id=p_client_request_id;IF req.resp