CREATE OR REPLACE FUNCTION public.get_project_payment_certifications(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$BEGIN IF auth.uid()IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PAYMENT_CERTIFICATION_FORBIDDEN'USING ERRCODE='42501';END IF;RETURN jsonb_build_object('projectId',p_project_id,'cases',COALESCE((SELECT jsonb_agg(jsonb_build_object('certificationCaseId',c.id,'caseNumber',c.case_number,'status',c.status,'milestoneId',c.milestone_id,'milestoneTitle',m.title,'plannedAmount',m.planned_amount,'currencyCode',s.currency_code,'openedAt',c.opened_at,'evidence',jsonb_build_object('contractMilestoneAmount',e.contract_milestone_amount,'requiredProgress',e.required_progress,'contractorReportedProgress',e.contractor_reported_progress,'pmVerifiedProgress',e.pm_verified_progress,'pmVerifiedAt',e.pm_verified_at,'scheduleProgress',e.schedule_progress,'boqQuantityProgress',e.boq_quantity_progress,'boqQuantityEvidenceAvailable',e.boq_quantity_evidence_available,'openCriticalIssueCount',e.open_critical_issue_count,'openSnagCount',e.open_snag_count,'pendingVariationCount',e.pending_variation_count,'pendingVariationExposure',e.pending_variation_exposure,'documents',e.documents,'evidenceNote',e.evidence_note,'evidenceReady',e.evidence_ready,'capturedAt',e.captured_at),'decisions',COALESCE((SELECT jsonb_agg(jsonb_build_object('decisionId',d.id,'decisionNumber',d.decision_number,'decisionType',d.decision_type,'certifiedAmount',d.certified_amount,'heldAmount',d.held_amount,'decisionReason',d.decision_reason,'evidenceReadyAtDecision',d.evidence_ready_at_decision,'decidedAt',d.decided_at)ORDER BY d.decision_number)FROM public.project_payment_certification_decisions d WHERE d.certification_case_id=c.id),'[]'::jsonb))ORDER BY c.case_number DESC)FROM public.project_payment_certification_cases c JOIN public.project_payment_certification_evidence e ON e.certification_case_id=c.id JOIN public.pro