CREATE OR REPLACE FUNCTION public.save_project_payment_closeout(p_project_id bigint,p_closeout_id uuid,p_future_obligations text,p_payment_explanation text,p_confirm boolean,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE u uuid:=auth.uid();role_name text;req public.write_command_requests%ROWTYPE;s public.project_payment_schedules%ROWTYPE;t public.project_payment_retention_terms%ROWTYPE;contract numeric;certified numeric;paid numeric;released numeric;held numeric;outstanding numeric;version_no integer;state text;result jsonb;
BEGIN SELECT upper(role)INTO role_name FROM public.profiles WHERE id=u;IF u IS NULL OR role_name NOT IN('PM','ADMIN')OR public.can_write_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PROJECT_PAYMENT_CLOSEOUT_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_closeout_id IS NULL OR p_client_request_id IS NULL OR btrim(COALESCE(p_future_obligations,''))=''OR char_length(p_future_obligations)>3000 OR btrim(COALESCE(p_payment_explanation,''))=''OR char_length(p_payment_explanation)>3000 THEN RAISE EXCEPTION'INVALID_PROJECT_PAYMENT_CLOSEOUT'USING ERRCODE='22023';END IF;INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'project_closeout.payment.save',p_client_request_id,p_project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT*INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='project_closeout.payment.save'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;IF EXISTS(SELECT 1 FROM public.project_payment_closeout_versions WHERE project_id=p_project_id AND status='CONFIRMED')THEN RAISE EXCEPTION'PROJECT_PAYMENT_CLOSEOUT_ALREADY_CONFIRMED'USING ERRCODE='55000';END IF;SELECT*INTO s FROM public.project_payment_schedules WHERE project_id=p_project_id ORDER BY(status='ACTIVE')DESC,version_number DESC LIMIT 1;IF s.id IS NULL THEN RAISE EXCEPTION'PAYMENT_CLOSEOUT_REQUIRES_PAYMENT_SCHEDULE'USING ERRCODE='55000';END IF;SELECT*INTO t FROM public.project_payment_retention_terms WHERE payment_schedule_id=s.id;contract:=s.contract_value;SELECT COALESCE(sum(x.certified_amount),0)INTO certified FROM(SELECT DISTINCT ON(certification_case_id)certification_case_id,certified_amount FROM public.project_payment_certification_decisions WHERE project_id=p_project_id AND decision_type IN('FULL','PARTIAL')ORDER BY certification_case_id,decision_number DESC)x;SELECT COALESCE(sum(amount),0)INTO paid FROM public.