CREATE OR REPLACE FUNCTION public.seal_historical_project_record(p_project_id bigint,p_record_id uuid,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE u uuid:=auth.uid();role_name text;req public.write_command_requests%ROWTYPE;pr public.projects%ROWTYPE;body jsonb;hash text;result jsonb;BEGIN SELECT upper(role)INTO role_name FROM public.profiles WHERE id=u;IF u IS NULL OR role_name NOT IN('PM','ADMIN')OR public.can_write_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'HISTORICAL_PROJECT_RECORD_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_record_id IS NULL OR p_client_request_id IS NULL THEN RAISE EXCEPTION'INVALID_HISTORICAL_PROJECT_RECORD_COMMAND'USING ERRCODE='22023';END IF;INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'project_closeout.history.seal',p_client_request_id,p_project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT*INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='project_closeout.history.seal'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;IF EXISTS(SELECT 1 FROM public.historical_project_records WHERE project_id=p_project_id)THEN RAISE EXCEPTION'HISTORICAL_PROJECT_RECORD_ALREADY_SEALED'USING ERRCODE='55000';END IF;IF NOT(EXISTS(SELECT 1 FROM public.project_cost_closeout_versions WHERE project_id=p_project_id AND status='CONFIRMED')AND EXISTS(SELECT 1 FROM public.project_schedule_closeout_versions WHERE project_id=p_project_id AND status='CONFIRMED')AND EXISTS(SELECT 1 FROM public.project_scope_closeout_versions WHERE project_id=p_project_id AND status='CONFIRMED')AND EXISTS(SELECT 1 FROM public.project_quality_closeout_versions WHERE project_id=p_project_id AND status='CONFIRMED')AND EXISTS(SELECT 1 FROM public.project_variation_closeout_versions WHERE project_id=p_project_id AND status='CONFIRMED')AND EXISTS(SELECT 1 FROM public.project_payment_closeout_versions WHERE project_id=p_project_id AND status='CONFIRMED')AND EXISTS(SELECT 1 FROM public.project_lessons_learned_versions WHERE project_id=p_project_id AND status='CONFIRMED')AND EXISTS(SELECT 1 FROM public.project_contractor_scorecards WHERE project_id=p_project_id AND status='CONFIRMED'))THEN RAISE EXCEPTION'HISTORICAL_RECORD_REQUIRES_ALL_CONFIRMED_CLOSEOUTS'USING ERRCODE='55000';END IF;SELECT*INTO pr FROM public.projects WHERE id=p_project_id;
body:=jsonb_build_object('schemaVersion',1,'project',to_jsonb(pr)-'created_by','cost',(SELECT to_jsonb(x)-'created_by'FROM public.project_cost_closeout_versions x WHERE project_id=p_project_id AND status='CONFIRMED'),'schedule',(SELECT to_jsonb(x)-'created_by'FROM public.project_schedule_closeout_versions x WHERE project_id=p_project_id AND status='CONFIRMED'),'scope',(SELECT to_jsonb(x)-'created_by'FROM public.project_scope_closeout_versions x WHERE project_id=p_project_id AND status='CONFIRMED'),'quality',(SELECT to_jsonb(x)-'created_by'FROM public.project_quality_closeout_versions x WHERE project_id=p_project_id AND status='CONFIRMED'),'variations',(SELECT to_jsonb(x)-'created_by'FROM public.project_variation_closeout_versions x WHERE project_id=p_project_id AND status='CONFIRMED'),'payments',(SELECT to_jsonb(x)-'created_by'FROM public.project_payment_closeout_versions x WHERE project_id=p_project_id AND status='CONFIRMED'),'lessons',(SELECT to_jsonb(x)-'created_by'FROM public.project_lessons_learned_versions x WHERE project_id=p_project_id AND status='CONFIRMED'),'contractorScorecard',(SELECT to_jsonb(x)-'created_by'FROM public.project_contractor_scorecards x WHERE project_id=p_project_id AND status='CONFIRMED'));hash:=md5(body::text);INSERT INTO public.historical_project_records VALUES(p_record_id,p_project_id,1,pr.work_ontology_version_id,body,hash,u,now());result:=jsonb_build_object('recordId',p_record_id,'projectId',p_project_id,'recordVersion',1,'payloadHash',hash,'sealedAt',now());UPDATE public.write_command_requests SET response=result,completed_at=now()WHERE id=req.id;RETURN result||jsonb_build_object('idempotentReplay',false);END;$$;
CREATE OR REPLACE FUNCTION public.get_historical_project_record(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$DECLARE x public.historical_project_records%ROWTYPE;BEGIN IF auth.uid()IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'HISTORICAL_PROJECT_RECORD_FORBIDDEN'USING ERRCODE='42501';END IF;SELECT*INTO x FROM public.historical_project_records WHERE project_id=p_project_id;RETURN jsonb_build_object('projectId',p_project_id,'isSealed',x.id IS NOT NULL,'record',CASE WHEN x.id IS NULL THEN NULL ELSE jsonb_build_object('recordId',x.id,'recordVersion',x.record_version,'ontologyVersionId',x.ontology_version_id,'payload',x.payload,'payloadHash',x.payload_hash,'sealedAt',x.sealed_at)END);END;$$;REVOKE ALL ON FUNCTION private.prevent_historical_record_mutation()FROM PUBLIC,anon,authenticated,service_role;REVOKE ALL ON FUNCTION public.seal_historical_project_record(bigint,uuid,uuid),public.get_historical_project_record(bigint)FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.seal_historical_project_record(bigint,uuid,uuid),public.get_historical_project_record(bigint)TO authenticated;

-- MIGRATION 106_historical_project_intelligence.sql SHA256 c164d7199fb179fe4d5f658faf3cd152eb5590a19b55b712260a2dbe9818c744
CREATE OR REPLACE FUNCTION public.get_historical_project_intelligence(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
DECLARE u uuid:=auth.uid();target public.historical_project_records%ROWTYPE;sample_count integer;comparables jsonb;costs jsonb;durations jsonb;budget_accuracy numeric;forecast_accuracy numeric;patterns jsonb;contractors jsonb;median_ratio numeric;
BEGIN IF u IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'HISTORICAL_INTELLIGENCE_FORBIDDEN'USING ERRCODE='42501';END IF;SELECT*INTO target FROM public.historical_project_records WHERE project_id=p_project_id;IF target.id IS NULL THEN RAISE EXCEPTION'HISTORICAL_INTELLIGENCE_REQUIRES_SEALED_PROJECT'USING ERRCODE='55000';END IF;
WITH eligible AS(SELECT h.* FROM public.historical_project_records h WHERE h.ontology_version_id IS NOT DISTINCT FROM target.ontology_version_id AND public.can_access_project(h.project_id))SELECT count(*),COALESCE(jsonb_agg(jsonb_build_object('projectId',project_id,'projectName',payload#>>'{project,shopping_mall_name}','storeCode',payload#>>'{project,store_code}','finalCost',payload#>>'{cost,final_cost}','awardValue',payload#>>'{cost,award_value}','completionVarianceDays',payload#>>'{schedule,completion_variance_days}','contractor',payload#>>'{contractorScorecard,contractor_name}','contractorScore',payload#>>'{contractorScorecard,overall_score}')ORDER BY sealed_at DESC),'[]')INTO sample_count,comparables FROM eligible;
WITH e AS(SELECT(payload#>>'{cost,final_cost}')::numeric final_cost,(payload#>>'{cost,award_value}')::numeric award_value,(payload#>>'{cost,approved_budget}')::numeric budget,(payload#>>'{cost,latest_forecast}')::numeric forecast,(payload#>>'{schedule,completion_variance_days}')::numeric duration_variance FROM public.historical_project_records WHERE ontology_version_id IS NOT DISTINCT FROM target.ontology_version_id AND public.can_access_project(project_id)),stats AS(SELECT percentile_cont(.5)WITHIN GROUP(ORDER BY final_cost)median_final,avg(final_cost)avg_final,min(final_cost)min_final,max(final_cost)max_final,percentile_cont(.5)WITHIN GROUP(ORDER BY duration_variance)median_duration,avg(duration_variance)avg_duration,avg(abs(final_cost-budget)*100/NULLIF(budget,0))budget_error,avg(abs(final_cost-forecast)*100/NULLIF(forecast,0))forecast_error,percentile_cont(.5)WITHIN GROUP(ORDER BY final_cost/NULLIF(award_value,0))ratio FROM e)SELECT jsonb_build_object('medianFinalCost',median_final,'averageFinalCost',round(avg_final,2),'minimumFinalCost',min_final,'maximumFinalCost',max_final),jsonb_build_object('medianCompletionVarianceDays',median_duration,'averageCompletionVarianceDays',round(avg_duration,2)),round(100-LEAST(COALESCE(budget_error,100),100),2),round(100-LEAST(COALESCE(forecast_error,100),100),2),ratio INTO costs,durations,budget_accuracy,forecast_accuracy,median_ratio FROM stats;
SELECT COALESCE(jsonb_agg(jsonb_build_object('reasonCode',reason_code,'variationCount',variation_count,'approvedValue',approved_value)ORDER BY variation_count DESC),'[]')INTO patterns FROM(SELECT reason->>'reasonCode'reason_code,sum((reason->>'variationCount')::integer)variation_count,sum((reason->>'approvedValue')::numeric)approved_value FROM public.historical_project_records h CROSS JOIN LATERAL jsonb_array_elements(h.payload#>'{variations,main_reasons}')reason WHERE h.ontology_version_id IS NOT DISTINCT FROM target.ontology_version_id AND public.can_access_project(h.project_id)GROUP BY reason->>'reasonCode')x;
SELECT COALESCE(jsonb_agg(jsonb_build_object('contractorName',name,'projectCount',projects,'averageScore',round(score,2))ORDER BY score DESC),'[]')INTO contractors FROM(SELECT payload#>>'{contractorScorecard,contractor_name}'name,count(*)projects,avg((payload#>>'{contractorScorecard,overall_score}')::numeric)score FROM public.historical_project_records h WHERE h.ontology_version_id IS NOT DISTINCT FROM target.ontology_version_id AND public.can_access_project(h.project_id)GROUP BY payload#>>'{contractorScorecard,contractor_name}')x;
RETURN jsonb_build_object('projectId',p_project_id,'evidenceSource','SEALED_HISTORICAL_PROJECT_RECORDS','sampleSize',sample_count,'comparableProjects',comparables,'costBenchmarks',costs,'durationBenchmarks',durations,'budgetAccuracyScore',budget_accuracy,'forecastAccuracyScore',forecast_accuracy,'variationPatterns',patterns,'contractorPerformance',contractors,'futureBudgetIntelligence',jsonb_build_object('recommendedAwardToFinalFactor',round(COALESCE(median_ratio,1),4),'confidence',CASE WHEN sample_count>=10 THEN'HIGH'WHEN sample_count>=3 THEN'MEDIUM'ELSE'LOW'END,'sampleSize',sample_count,'warning',CASE WHEN sample_count<3 THEN'Insufficient comparable history; use as directional evidence only.'ELSE NULL END));END;$$;
REVOKE ALL ON FUNCTION public.get_historical_project_intelligence(bigint)FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.get_historical_project_intelligence(bigint)TO authenticated;

-- MIGRATION 107_verified_management_outputs.sql SHA256 f4cc23bf8f66d04ebedb565ffe522dce31397d4dc7dad3a159879519423076a1
CREATE OR REPLACE FUNCTION public.get_verified_management_outputs(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$DECLARE u uuid:=auth.uid();h public.historical_project_records%ROWTYPE;i jsonb;tender jsonb;budget jsonb;narrative jsonb;recommendations jsonb:='[]'::jsonb;BEGIN IF u IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'MANAGEMENT_OUTPUTS_FORBIDDEN'USING ERRCODE='42501';END IF;SELECT*INTO h FROM public.historical_project_records WHERE project_id=p_project_id;IF h.id IS NULL THEN RAISE EXCEPTION'MANAGEMENT_OUTPUTS_REQUIRE_SEALED_PROJECT'USING ERRCODE='55000';END IF;i:=public.get_historical_project_intelligence(p_project_id);
tender:=jsonb_build_object('title','Tender Commercial Summary','contractor',h.payload#>>'{contractorScorecard,contractor_name}','awardValue',h.payload#>'{cost,award_value}','currencyCode',h.payload#>>'{cost,currency_code}','finalApprovedVariations',h.payload#>'{variations,final_approved_variation_value}','finalCost',h.payload#>'{cost,final_cost}','varianceToAward',h.payload#>'{cost,variance_to_award}','commercialOutcome',CASE WHEN(h.payload#>>'{cost,variance_to_award}')::numeric<=0 THEN'AT_OR_BELOW_AWARD'ELSE'ABOVE_AWARD'END);
budget:=jsonb_build_object('title','Budget Management Summary','approvedBudget',h.payload#>'{cost,approved_budget}','awardValue',h.payload#>'{cost,award_value}','latestForecast',h.payload#>'{cost,latest_forecast}','finalCost',h.payload#>'{cost,final_cost}','varianceToBudget',h.payload#>'{cost,variance_to_budget}','budgetAccuracyScore',i->'budgetAccuracyScore','forecastAccuracyScore',i->'forecastAccuracyScore');
narrative:=jsonb_build_object('title','Forecast and Closeout Narrative','statements',jsonb_build_array('Final cost: '||(h.payload#>>'{cost,final_cost}')||' '||(h.payload#>>'{cost,currency_code}'),'Completion variance: '||(h.payload#>>'{schedule,completion_variance_days}')||' days','Snags at handover: '||(h.payload#>>'{quality,open_at_handover}'),'Approved variations: '||(h.payload#>>'{variations,approved_count}')||', rejected: '||(h.payload#>>'{variations,rejected_count}'),'Outstanding certified payments: '||(h.payload#>>'{payments,outstanding_value}')||' '||(h.payload#>>'{payments,currency_code}')),'sourceRecordId',h.id,'sourceHash',h.payload_hash);
IF(h.payload#>>'{cost,variance_to_budget}')::numeric>0 THEN recommendations:=recommendations||jsonb_build_array(jsonb_build_object('priority','HIGH','area','BUDGET','recommendation','Apply the historical award-to-final factor during future budget approval.','evidence',i#>'{futureBudgetIntelligence,recommendedAwardToFinalFactor}'));END IF;IF(h.payload#>>'{schedule,completion_variance_days}')::integer>0 THEN recommendations:=recommendations||jsonb_build_array(jsonb_build_object('priority','HIGH','area','SCHEDULE','recommendation','Use recorded delay drivers and recovery actions when approving the next baseline.','evidence',h.payload#>'{schedule,delay_drivers}'));END IF;IF(h.payload#>>'{quality,open_at_handover}')::integer>0 THEN recommendations:=recommendations||jsonb_build_array(jsonb_build_object('priority','MEDIUM','area','QUALITY','recommendation','Introduce earlier Work Group snag closure gates before handover.','evidence',h.payload#>'{quality,snags_by_work_group}'));END IF;IF(h.payload#>>'{variations,pending_count}')::integer>0 THEN recommendations:=recommendations||jsonb_build_array(jsonb_build_object('priority','HIGH','area','COMMERCIAL','recommendation','Do not seal future projects with unresolved variation exposure.','evidence',h.payload#>'{variations,pending_count}'));END IF;IF jsonb_array_length(recommendations)=0 THEN recommendations:=jsonb_build_array(jsonb_build_object('priority','LOW','area','CONTINUOUS_IMPROVEMENT','recommendation','Reuse the confirmed lessons learned and contractor scorecard on the next comparable project.','evidence',h.payload#>'{lessons,change_next_time}'));END IF;
RETURN jsonb_build_object('projectId',p_project_id,'verifiedSource',jsonb_build_object('recordId',h.id,'payloadHash',h.payload_hash,'sealedAt',h.sealed_at),'tenderCommercialSummary',tender,'budgetManagementSummary',budget,'forecastCloseoutNarrative',narrative,'managementRecommendations',recommendations,'generationMethod','DETERMINISTIC_STRUCTURED_DATA_RULES');END;$$;REVOKE ALL ON FUNCTION public.get_verified_management_outputs(bigint)FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.get_verified_management_outputs(bigint)TO authenticated;

