-- MIGRATION 138_admin_user_command_boundary.sql SHA256 98641adff480a2a277017fb7acccf5d75c77565b1c333134f737ea69e29dba04
CREATE TABLE IF NOT EXISTS public.admin_user_change_events(
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  target_user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  company_id text,
  previous_name text,
  new_name text,
  previous_role text NOT NULL,
  new_role text NOT NULL,
  previous_assigned_projects integer[] NOT NULL,
  new_assigned_projects integer[] NOT NULL,
